window.TRANSCRIPTS = {"knowledge-tracing-bkt-dkt":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.04,"end":2.194,"text":"Every right or wrong answer is a clue"},{"start":2.194,"end":3.725,"text":"about what a learner knows."},{"start":4.065,"end":6.503,"text":"Knowledge tracing turns those clues into a"},{"start":6.503,"end":7.467,"text":"running estimate."},{"start":7.807,"end":10.188,"text":"This video goes from the classic Bayesian"},{"start":10.188,"end":12.513,"text":"model to deep learning, and the debate"},{"start":12.513,"end":13.25,"text":"between them."},{"start":15.15,"end":17.264,"text":"A tutor sees a stream of answers for one"},{"start":17.264,"end":17.574,"text":"skill."},{"start":17.883,"end":19.894,"text":"It has to guess what the learner knows"},{"start":19.894,"end":22.111,"text":"now, and whether the next answer will be"},{"start":22.111,"end":22.421,"text":"right."},{"start":25.9,"end":28.709,"text":"Knowledge tracing, from Albert Corbett and"},{"start":28.709,"end":30.831,"text":"John Anderson in the mid nineteen"},{"start":30.831,"end":33.328,"text":"nineties, now usually called Bayesian"},{"start":33.328,"end":36.074,"text":"knowledge tracing, treats each skill as a"},{"start":36.074,"end":38.945,"text":"hidden switch: known, or not yet known."},{"start":39.77,"end":42.05,"text":"At each practice opportunity, an unknown"},{"start":42.05,"end":44.33,"text":"skill can switch to known with probability"},{"start":44.33,"end":44.701,"text":"P of T."},{"start":45.02,"end":47.247,"text":"In the classic model, it never switches"},{"start":47.247,"end":47.512,"text":"back."},{"start":48.32,"end":50.732,"text":"We never see the switch, only answers."},{"start":51.094,"end":53.626,"text":"A learner who does not know the skill can"},{"start":53.626,"end":56.219,"text":"still guess right, with probability P of"},{"start":56.219,"end":56.339,"text":"G."},{"start":56.701,"end":59.113,"text":"One who knows it can still slip, with"},{"start":59.113,"end":60.258,"text":"probability P of S."},{"start":61.17,"end":63.194,"text":"Add the chance the skill was already known"},{"start":63.194,"end":65.265,"text":"at the start, P of L zero, and you have"},{"start":65.265,"end":66.348,"text":"four numbers per skill."},{"start":68.22,"end":70.398,"text":"Let's run one update by hand, with a"},{"start":70.398,"end":72.13,"text":"starting belief of point three."},{"start":72.465,"end":74.923,"text":"The first answer is wrong, so Bayes' rule"},{"start":74.923,"end":77.04599999999999,"text":"lowers the belief to about point zero"},{"start":77.04599999999999,"end":77.325,"text":"five."},{"start":79.21000000000001,"end":81.431,"text":"Then the model adds a chance to learn from"},{"start":81.431,"end":83.496,"text":"the practice itself, which brings the"},{"start":83.496,"end":85.51,"text":"belief back up to about point one nine."},{"start":87.38,"end":89.797,"text":"Over eight answers the belief rises and"},{"start":89.797,"end":92.637,"text":"falls: each mistake pulls it down, each"},{"start":92.637,"end":94.87299999999999,"text":"success pushes it up, and a run of"},{"start":94.87299999999999,"end":96.92699999999999,"text":"successes carries it close to one."},{"start":97.81,"end":100.219,"text":"If a tutor sets a mastery threshold, say"},{"start":100.219,"end":102.51599999999999,"text":"point nine five, it can decide when to"},{"start":102.51599999999999,"end":102.964,"text":"move on."},{"start":104.9,"end":106.868,"text":"The big strength of this model is that"},{"start":106.868,"end":108.987,"text":"every number means something to a teacher."},{"start":109.28999999999999,"end":111.207,"text":"A low learning rate says the skill is"},{"start":111.207,"end":111.964,"text":"learned slowly."},{"start":112.267,"end":114.285,"text":"A high guess rate says right answers on"},{"start":114.285,"end":115.64699999999999,"text":"that skill tell you little."},{"start":117.56700000000001,"end":119.765,"text":"In two thousand fifteen, Chris Piech and"},{"start":119.765,"end":121.708,"text":"colleagues replaced the switch with a"},{"start":121.708,"end":122.986,"text":"recurrent neural network."},{"start":123.292,"end":125.286,"text":"Deep knowledge tracing reads the whole"},{"start":125.286,"end":126.82,"text":"sequence of items and answers."},{"start":127.67699999999999,"end":129.888,"text":"At each step it outputs the chance of"},{"start":129.888,"end":131.983,"text":"answering every item correctly next."},{"start":132.332,"end":134.834,"text":"No expert has to say which skill each item"},{"start":134.834,"end":135.358,"text":"measures."},{"start":137.347,"end":140.005,"text":"The paper reported a striking result: on"},{"start":140.005,"end":142.663,"text":"one benchmark, an AUC of point eight six,"},{"start":142.663,"end":144.743,"text":"against point six nine for the best"},{"start":144.743,"end":145.61,"text":"earlier result."},{"start":147.61,"end":149.694,"text":"Within a year, two papers took a closer"},{"start":149.694,"end":149.942,"text":"look."},{"start":151.94,"end":154.547,"text":"Xiaolu Xiong and colleagues found that"},{"start":154.547,"end":157.155,"text":"nearly a quarter of the benchmark rows"},{"start":157.155,"end":160.297,"text":"were duplicates, and that on cleaned data,"},{"start":160.297,"end":163.305,"text":"deep knowledge tracing still beat BKT, but"},{"start":163.305,"end":166.046,"text":"held no overall edge over another simple"},{"start":166.046,"end":167.049,"text":"model, P F A."},{"start":167.92000000000002,"end":170.06,"text":"Mohammad Khajah and colleagues extended"},{"start":170.06,"end":171.772,"text":"Bayesian knowledge tracing with"},{"start":171.772,"end":174.072,"text":"forgetting, student ability, and skill"},{"start":174.072,"end":176.211,"text":"discovery, and its performance became"},{"start":176.211,"end":178.405,"text":"indistinguishable from the deep model,"},{"start":178.405,"end":180.491,"text":"suggesting the deep model's gains came"},{"start":180.491,"end":182.791,"text":"from patterns that simpler models can also"},{"start":182.791,"end":183.219,"text":"capture."},{"start":185.133,"end":187.8,"text":"We ran our own small test: six hundred"},{"start":187.8,"end":189.981,"text":"simulated students practicing three"},{"start":189.981,"end":192.648,"text":"fraction skills, with a hidden dependency"},{"start":192.648,"end":193.86,"text":"between two of them."},{"start":194.743,"end":197.402,"text":"On the held out students, BKT reached an"},{"start":197.402,"end":200.185,"text":"AUC of point eight zero nine, and the deep"},{"start":200.185,"end":201.978,"text":"model point eight zero seven."},{"start":202.349,"end":205.008,"text":"In this one small simulation, the simple"},{"start":205.008,"end":206.492,"text":"model did about as well."},{"start":208.327,"end":211.369,"text":"Later models use attention, such as SAKT"},{"start":211.369,"end":211.935,"text":"and AKT."},{"start":212.36,"end":215.332,"text":"But the core trade off remains: deep"},{"start":215.332,"end":218.233,"text":"models can predict well on large data,"},{"start":218.233,"end":220.992,"text":"while BKT's numbers tell a teacher why."},{"start":221.877,"end":224.54,"text":"So choose a learner model by the decision"},{"start":224.54,"end":227.076,"text":"it needs to support, not by AUC alone."},{"start":229.077,"end":231.24099999999999,"text":"For the discussion board, pick one"},{"start":231.24099999999999,"end":233.698,"text":"tutoring decision, such as moving on or"},{"start":233.698,"end":236.038,"text":"alerting a teacher, and explain which"},{"start":236.038,"end":238.612,"text":"learner model you would trust for it, and"},{"start":238.612,"end":238.846,"text":"why."}]},"iEc8Dt3ePWo":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.538,"text":"When a learning game adapts to a player,"},{"start":2.538,"end":5.136,"text":"it can change two very different things:"},{"start":5.136,"end":7.791,"text":"what happens right now, inside a level, or"},{"start":7.791,"end":9.711,"text":"what comes next, between levels."},{"start":10.05,"end":11.631,"text":"This video compares the two."},{"start":13.587,"end":15.914,"text":"Back in Launch Lab, player B has missed"},{"start":15.914,"end":18.075,"text":"the target three times in a row on the"},{"start":18.075,"end":18.684,"text":"same level."},{"start":20.547,"end":22.37,"text":"A game could respond in two ways."},{"start":22.702,"end":25.023,"text":"It could step in now with a hint, or it"},{"start":25.023,"end":27.289,"text":"could send player B to a different level"},{"start":27.289,"end":27.565,"text":"next."},{"start":32.767,"end":34.904,"text":"Both are adaptation, but they work on"},{"start":34.904,"end":36.935,"text":"different timescales, use different"},{"start":36.935,"end":38.966,"text":"evidence, and carry different risks."},{"start":41.087,"end":43.847,"text":"Micro adaptation happens inside a task,"},{"start":43.847,"end":47.067,"text":"from moment to moment: hints, feedback,"},{"start":47.067,"end":49.761,"text":"small changes to pacing or difficulty,"},{"start":49.761,"end":51.732,"text":"even how a character responds."},{"start":52.547,"end":54.947,"text":"Michael Kickmeier-Rust and Dietrich Albert"},{"start":54.947,"end":57.236,"text":"argued that in games, micro adaptivity"},{"start":57.236,"end":59.525,"text":"should be subtle, so that help arrives"},{"start":59.525,"end":61.032,"text":"without breaking immersion."},{"start":62.877,"end":65.583,"text":"Macro adaptation happens between tasks:"},{"start":65.583,"end":67.929,"text":"which level comes next, which path a"},{"start":67.929,"end":70.515,"text":"learner takes, and how fast the sequence"},{"start":70.515,"end":70.876,"text":"moves."},{"start":72.857,"end":74.491,"text":"The idea is older than games."},{"start":74.82900000000001,"end":77.252,"text":"Ok-Choon Park and Jung Lee described macro"},{"start":77.252,"end":79.674,"text":"adaptive instruction, which fits a whole"},{"start":79.674,"end":82.09700000000001,"text":"program to what we know about a learner,"},{"start":82.09700000000001,"end":84.351,"text":"and micro adaptive instruction, which"},{"start":84.351,"end":86.549,"text":"diagnoses needs during learning itself."},{"start":88.34700000000001,"end":90.857,"text":"Kurt VanLehn gave the same split a name in"},{"start":90.857,"end":93.542,"text":"tutoring systems: an inner loop for each"},{"start":93.542,"end":95.876,"text":"step, and an outer loop for each task."},{"start":97.91,"end":100.563,"text":"Micro adaptation acts in seconds, using"},{"start":100.563,"end":102.142,"text":"what the player just did."},{"start":102.521,"end":105.301,"text":"Macro adaptation acts over minutes, using"},{"start":105.301,"end":107.701,"text":"a learner model built from many tasks."},{"start":108.61,"end":111.59,"text":"Micro changes hints, feedback, and local"},{"start":111.59,"end":114.107,"text":"difficulty, while macro changes the"},{"start":114.107,"end":116.82300000000001,"text":"sequence, the level, and the content."},{"start":118.08,"end":119.532,"text":"Each one has its own risk."},{"start":119.86699999999999,"end":122.212,"text":"Micro help that comes too often can break"},{"start":122.212,"end":124.725,"text":"flow, or let players lean on hints instead"},{"start":124.725,"end":125.395,"text":"of thinking."},{"start":126.31,"end":128.66,"text":"Macro decisions can send a player down the"},{"start":128.66,"end":131.23,"text":"wrong path, and they react slowly, because"},{"start":131.23,"end":133.252,"text":"they wait for evidence to accumulate."},{"start":135.117,"end":137.588,"text":"To see how the two loops interact, we"},{"start":137.588,"end":140.122,"text":"simulated two thousand players in Launch"},{"start":140.122,"end":143.15,"text":"Lab under four designs: a fixed sequence,"},{"start":143.15,"end":145.436,"text":"macro only, micro only, and both."},{"start":147.447,"end":150.018,"text":"The rules are simple and stated up front:"},{"start":150.018,"end":152.317,"text":"players learn most when success is likely"},{"start":152.317,"end":154.67000000000002,"text":"but not certain, hints help them succeed"},{"start":154.67000000000002,"end":157.077,"text":"but teach a little less, and three misses"},{"start":157.077,"end":158.828,"text":"in a row can make a player quit."},{"start":165.007,"end":167.476,"text":"With a fixed sequence, fifty eight percent"},{"start":167.476,"end":169.835,"text":"of players quit early, and almost all of"},{"start":169.835,"end":171.097,"text":"the weakest third quit."},{"start":171.947,"end":174.28,"text":"Hints alone barely help: forty seven"},{"start":174.28,"end":176.724,"text":"percent still quit, because a hint cannot"},{"start":176.724,"end":178.723,"text":"rescue a level that is far too hard."},{"start":179.527,"end":182.181,"text":"Choosing the next level well matters more:"},{"start":182.181,"end":184.448,"text":"macro adaptation cuts quitting to twenty"},{"start":184.448,"end":186.66,"text":"one percent, and combining both loops"},{"start":186.66,"end":188.595,"text":"brings it down to fourteen percent."},{"start":190.627,"end":192.034,"text":"There is a catch, though."},{"start":192.346,"end":194.431,"text":"Under macro adaptation, the strongest"},{"start":194.431,"end":196.568,"text":"players learned less than with the fixed"},{"start":196.568,"end":198.548,"text":"sequence, because the learner model"},{"start":198.548,"end":200.789,"text":"started at average and took several levels"},{"start":200.789,"end":201.414,"text":"to catch up."},{"start":205.3,"end":207.449,"text":"The game Reboot Seoul twenty fifty uses"},{"start":207.449,"end":209.222,"text":"both loops in its drone missions."},{"start":209.544,"end":211.801,"text":"The macro loop moves players through five"},{"start":211.801,"end":214.003,"text":"tiers, from small grids to larger ones"},{"start":214.003,"end":215.508,"text":"with tighter command limits."},{"start":216.45,"end":218.373,"text":"The micro loop watches for repeated"},{"start":218.373,"end":220.563,"text":"trouble inside a mission and offers help"},{"start":220.563,"end":223.02,"text":"in steps: first an explanation, then a"},{"start":223.02,"end":224.195,"text":"map, then more time."},{"start":224.515,"end":226.70499999999998,"text":"Support fades once a player clears a new"},{"start":226.70499999999998,"end":227.4,"text":"tier cleanly."},{"start":229.24,"end":231.531,"text":"So when you design adaptivity for a"},{"start":231.531,"end":234.204,"text":"learning game, decide what each loop is"},{"start":234.204,"end":237.131,"text":"for: micro to keep a player productively"},{"start":237.131,"end":239.93200000000002,"text":"engaged in this task, and macro to choose"},{"start":239.93200000000002,"end":241.968,"text":"the task that teaches most next."},{"start":242.97,"end":245.516,"text":"Then check three things: does the help"},{"start":245.516,"end":248.061,"text":"protect immersion, does the learner model"},{"start":248.061,"end":250.607,"text":"have enough evidence, and can the learner"},{"start":250.607,"end":253.152,"text":"see or choose the change, which Jan Plass"},{"start":253.152,"end":255.293,"text":"and Shashank Pawar call adaptability."},{"start":257.257,"end":259.516,"text":"For the discussion board, think of a game"},{"start":259.516,"end":261.723,"text":"you know and find one micro adaptation and"},{"start":261.723,"end":263.11,"text":"one macro adaptation in it."},{"start":263.418,"end":265.677,"text":"Then ask what evidence each one uses, and"},{"start":265.677,"end":267.731,"text":"what would happen if that evidence were"},{"start":267.731,"end":268.039,"text":"wrong."}]},"aADMw1NjWKU":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.351,"text":"Why do children spend hours on some games,"},{"start":2.351,"end":3.441,"text":"and minutes on others?"},{"start":3.739,"end":5.821,"text":"In nineteen eighty, Thomas Malone asked"},{"start":5.821,"end":7.903,"text":"that question about computer games, and"},{"start":7.903,"end":9.638,"text":"turned the answer into a theory of"},{"start":9.638,"end":11.473,"text":"intrinsically motivating instruction."},{"start":13.41,"end":15.977,"text":"Malone's Stanford dissertation was titled"},{"start":15.977,"end":17.872,"text":"What Makes Things Fun to Learn?"},{"start":18.239,"end":20.745,"text":"He studied which games children chose to"},{"start":20.745,"end":23.312,"text":"play, then built versions of games with"},{"start":23.312,"end":25.818,"text":"features added or removed, to see what"},{"start":25.818,"end":26.673,"text":"made them fun."},{"start":27.62,"end":29.842,"text":"In one study he took Darts, a fractions"},{"start":29.842,"end":32.276,"text":"game, and removed features one at a time,"},{"start":32.276,"end":34.763,"text":"such as scoring, music, and the fantasy of"},{"start":34.763,"end":36.033,"text":"arrows popping balloons."},{"start":37.04,"end":39.584,"text":"One finding stood out: boys liked the"},{"start":39.584,"end":42.188,"text":"version where arrows popped balloons, but"},{"start":42.188,"end":43.016,"text":"girls did not."},{"start":43.371,"end":45.382,"text":"The same fantasy did not motivate"},{"start":45.382,"end":45.915,"text":"everyone."},{"start":47.79,"end":50.137,"text":"In the journal Cognitive Science, in"},{"start":50.137,"end":52.785,"text":"nineteen eighty one, he organized what he"},{"start":52.785,"end":55.674,"text":"found into three ingredients: challenge,"},{"start":55.674,"end":57.179,"text":"fantasy, and curiosity."},{"start":59.043,"end":61.06,"text":"Challenge needs a goal whose outcome is"},{"start":61.06,"end":61.564,"text":"uncertain."},{"start":61.866,"end":64.135,"text":"If you are sure to win, or sure to lose,"},{"start":64.135,"end":66.101,"text":"there is little reason to keep playing."},{"start":66.813,"end":69.182,"text":"Malone listed ways to keep outcomes"},{"start":69.182,"end":72.34,"text":"uncertain: variable difficulty, goals at"},{"start":72.34,"end":75.235,"text":"several levels, hidden information, and"},{"start":75.235,"end":75.959,"text":"randomness."},{"start":77.873,"end":80.21600000000001,"text":"Fantasy places the player in an imagined"},{"start":80.21600000000001,"end":80.559,"text":"world."},{"start":80.901,"end":83.015,"text":"Malone's key distinction was between"},{"start":83.015,"end":85.301,"text":"extrinsic fantasy and intrinsic fantasy."},{"start":87.243,"end":89.332,"text":"In an extrinsic version of a fractions"},{"start":89.332,"end":91.688,"text":"game, you answer a question, and then a"},{"start":91.688,"end":93.991,"text":"cannon fires, whether or not the fantasy"},{"start":93.991,"end":95.812,"text":"has anything to do with fractions."},{"start":97.703,"end":100.051,"text":"In an intrinsic version, the fraction you"},{"start":100.051,"end":102.55799999999999,"text":"type is the aim: three quarters sends the"},{"start":102.55799999999999,"end":104.74600000000001,"text":"shot three quarters of the way, so the"},{"start":104.74600000000001,"end":106.293,"text":"fantasy depends on the skill."},{"start":107.093,"end":109.366,"text":"Malone argued that intrinsic fantasies are"},{"start":109.366,"end":111.163,"text":"usually more interesting and more"},{"start":111.163,"end":113.435,"text":"instructional, because every move in the"},{"start":113.435,"end":115.49600000000001,"text":"fantasy gives feedback about the skill."},{"start":117.363,"end":119.23400000000001,"text":"Curiosity comes in two kinds."},{"start":119.62100000000001,"end":122.265,"text":"Sensory curiosity is drawn by changes in"},{"start":122.265,"end":123.296,"text":"light and sound."},{"start":123.68299999999999,"end":126.392,"text":"Cognitive curiosity is drawn by the sense"},{"start":126.392,"end":128.714,"text":"that our knowledge is incomplete,"},{"start":128.714,"end":130.906,"text":"inconsistent, or unparsimonious."},{"start":131.713,"end":134.084,"text":"In the cannon game, a player who types two"},{"start":134.084,"end":136.35,"text":"quarters and then one half sees both shots"},{"start":136.35,"end":137.562,"text":"land in the same place."},{"start":137.878,"end":140.038,"text":"That small surprise invites the question"},{"start":140.038,"end":140.407,"text":"of why."},{"start":142.333,"end":145.552,"text":"Later, with Mark Lepper, Malone extended"},{"start":145.552,"end":148.913,"text":"the list: control, meaning choice and a"},{"start":148.913,"end":151.917,"text":"sense of power, and three interpersonal"},{"start":151.917,"end":155.636,"text":"motivations: cooperation, competition, and"},{"start":155.636,"end":156.494,"text":"recognition."},{"start":158.44299999999998,"end":160.778,"text":"Decades later, Jacob Habgood and Shaaron"},{"start":160.778,"end":163.112,"text":"Ainsworth tested a version of this idea,"},{"start":163.112,"end":165.446,"text":"which they called intrinsic integration,"},{"start":165.446,"end":167.618,"text":"with a math game called Zombie Division."},{"start":168.463,"end":170.642,"text":"Children learned more from the intrinsic"},{"start":170.642,"end":173.03300000000002,"text":"version under fixed time, and in free time"},{"start":173.03300000000002,"end":175.265,"text":"chose to play it about seven times longer."},{"start":176.173,"end":178.653,"text":"Later studies show a more mixed picture,"},{"start":178.653,"end":181.133,"text":"so treat intrinsic integration as a strong"},{"start":181.133,"end":183.267,"text":"design hypothesis, not a guarantee."},{"start":185.22,"end":187.368,"text":"When you design a learning game, check"},{"start":187.368,"end":189.621,"text":"whether the goal's outcome is uncertain,"},{"start":189.621,"end":191.926,"text":"whether the fantasy depends on the skill,"},{"start":191.926,"end":193.813,"text":"and whether feedback leaves players"},{"start":193.813,"end":194.756,"text":"curious about why."},{"start":196.73,"end":198.735,"text":"For the discussion board, pick an"},{"start":198.735,"end":201.073,"text":"educational game and classify its fantasy"},{"start":201.073,"end":202.52100000000002,"text":"as intrinsic or extrinsic."},{"start":202.855,"end":204.971,"text":"Then redesign one element so that the"},{"start":204.971,"end":206.92000000000002,"text":"fantasy depends on the skill being"},{"start":206.92000000000002,"end":207.36599999999999,"text":"learned."}]},"SfIj7mrAHwI":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.577,"text":"Every learning design hides a guess about"},{"start":2.577,"end":3.805,"text":"how learning happens."},{"start":4.156,"end":6.496,"text":"A conjecture map, laid out by William"},{"start":6.496,"end":9.129,"text":"Sandoval in a two thousand fourteen paper,"},{"start":9.129,"end":11.41,"text":"puts those guesses on paper so you can"},{"start":11.41,"end":11.995,"text":"test them."},{"start":12.346,"end":14.569,"text":"This video builds one, step by step."},{"start":16.34,"end":18.413,"text":"Sandoval noticed that most writing on"},{"start":18.413,"end":20.595,"text":"design research described what it is,"},{"start":20.595,"end":23.049,"text":"rather than how to do it, and critics were"},{"start":23.049,"end":24.413,"text":"asking for clearer rigor."},{"start":25.37,"end":27.654,"text":"His premise is simple: any learning"},{"start":27.654,"end":29.882,"text":"environment already embodies hypotheses"},{"start":29.882,"end":32.388,"text":"about how learning happens, so researchers"},{"start":32.388,"end":34.56,"text":"should state them explicitly, and in"},{"start":34.56,"end":35.006,"text":"advance."},{"start":36.867,"end":39.157,"text":"The map reads from left to right: a high"},{"start":39.157,"end":40.949,"text":"level conjecture is embodied in the"},{"start":40.949,"end":43.139,"text":"design, the embodiment produces mediating"},{"start":43.139,"end":45.18,"text":"processes, and those processes produce"},{"start":45.18,"end":45.628,"text":"outcomes."},{"start":46.457,"end":48.676,"text":"Two kinds of arrows connect the boxes."},{"start":49.026,"end":51.479,"text":"Design conjectures run from embodiment to"},{"start":51.479,"end":52.064,"text":"processes."},{"start":52.414,"end":54.925,"text":"Theoretical conjectures run from processes"},{"start":54.925,"end":55.626,"text":"to outcomes."},{"start":56.567,"end":59.034,"text":"The middle box is the one Sandoval insists"},{"start":59.034,"end":59.206,"text":"on."},{"start":59.55,"end":61.788,"text":"A mediating process is what the design"},{"start":61.788,"end":64.37,"text":"should make happen in between, and you can"},{"start":64.37,"end":66.435,"text":"see it in interactions, or in the"},{"start":66.435,"end":67.812,"text":"artifacts learners make."},{"start":70.787,"end":71.638,"text":"Let's build one."},{"start":71.957,"end":74.352,"text":"Our example is Recipe Remix, a sixth grade"},{"start":74.352,"end":76.48,"text":"fractions lesson where students scale a"},{"start":76.48,"end":78.555,"text":"cookie recipe for different numbers of"},{"start":78.555,"end":78.92699999999999,"text":"guests."},{"start":80.81700000000001,"end":83.451,"text":"Step one, the high level conjecture:"},{"start":83.451,"end":85.188,"text":"students understand fraction"},{"start":85.188,"end":87.404,"text":"multiplication better when they must"},{"start":87.404,"end":89.979,"text":"justify their scaling to a peer, using a"},{"start":89.979,"end":91.29599999999999,"text":"visual representation."},{"start":91.655,"end":94.41,"text":"It is too general, by design, to tell you"},{"start":94.41,"end":95.727,"text":"exactly what to build."},{"start":96.56700000000001,"end":98.094,"text":"Step two, the embodiment."},{"start":98.434,"end":100.866,"text":"Sandoval names four kinds of element:"},{"start":100.866,"end":103.24199999999999,"text":"tools and materials, task structures,"},{"start":103.24199999999999,"end":105.562,"text":"participant structures, and discursive"},{"start":105.562,"end":106.12700000000001,"text":"practices."},{"start":107.06700000000001,"end":109.947,"text":"Here that means recipe cards and fraction"},{"start":109.947,"end":113.17,"text":"strips, scaling for six, nine, and three"},{"start":113.17,"end":115.913,"text":"guests with a proof sketch each time,"},{"start":115.913,"end":118.382,"text":"pairs with a Chef who scales and an"},{"start":118.382,"end":121.194,"text":"Auditor who must be convinced, and the"},{"start":121.194,"end":123.525,"text":"talk move, show me how you know."},{"start":124.42699999999999,"end":126.322,"text":"A design does not need all four."},{"start":126.678,"end":129.107,"text":"In Ann Brown's design work, reciprocal"},{"start":129.107,"end":131.536,"text":"teaching changed tasks and roles without"},{"start":131.536,"end":132.661,"text":"any new technology."},{"start":133.547,"end":135.724,"text":"Step three, the mediating processes."},{"start":136.068,"end":138.703,"text":"You can see them in two ways: observable"},{"start":138.703,"end":141.225,"text":"interactions, like an Auditor challenging"},{"start":141.225,"end":143.574,"text":"and a Chef justifying with strips, and"},{"start":143.574,"end":145.923,"text":"artifacts, like annotated recipe cards."},{"start":146.767,"end":149.637,"text":"Sandoval's analogy: an airplane flies only"},{"start":149.637,"end":151.191,"text":"because it generates lift."},{"start":151.55,"end":154.36,"text":"Designs, likewise, do not lead directly to"},{"start":154.36,"end":154.898,"text":"outcomes."},{"start":156.767,"end":159.435,"text":"Step four, the outcomes, as specific as"},{"start":159.435,"end":161.86,"text":"you can make them: better fraction"},{"start":161.86,"end":163.922,"text":"multiplication scores, and more"},{"start":163.922,"end":165.923,"text":"justification in written answers."},{"start":167.953,"end":170.15800000000002,"text":"Now write each arrow as a sentence."},{"start":170.536,"end":173.245,"text":"The design conjecture: if pairs scale"},{"start":173.245,"end":175.575,"text":"recipes in Chef and Auditor roles,"},{"start":175.575,"end":177.78,"text":"justification exchanges will occur."},{"start":178.15800000000002,"end":180.993,"text":"The theoretical conjecture: if students"},{"start":180.993,"end":183.639,"text":"regularly justify with representations,"},{"start":183.639,"end":185.465,"text":"their understanding improves."},{"start":186.403,"end":189.349,"text":"Each arrow needs its own evidence: video,"},{"start":189.349,"end":191.993,"text":"interaction, or artifact analysis for the"},{"start":191.993,"end":194.698,"text":"design conjecture, and outcome measures,"},{"start":194.698,"end":197.223,"text":"on top of that, for the theoretical one."},{"start":199.177,"end":201.323,"text":"Now the map meets a real classroom, and"},{"start":201.323,"end":203.01,"text":"the evidence starts to talk back."},{"start":204.977,"end":207.255,"text":"Suppose quiz scores barely move, and"},{"start":207.255,"end":209.475,"text":"classroom video shows Auditors mostly"},{"start":209.475,"end":210.176,"text":"saying okay."},{"start":215.30700000000002,"end":217.377,"text":"The design arrow failed: the design never"},{"start":217.377,"end":218.91899999999998,"text":"produced the justification process."},{"start":219.183,"end":221.077,"text":"When the outcome is missing, first check"},{"start":221.077,"end":222.927,"text":"whether the middle box happened at all,"},{"start":222.927,"end":224.777,"text":"because a failed design tells you nothing"},{"start":224.777,"end":225.702,"text":"yet about the theory."},{"start":226.55700000000002,"end":229.302,"text":"So you revise the embodiment: an Auditor"},{"start":229.302,"end":231.987,"text":"checklist, and a class norm that an answer"},{"start":231.987,"end":234.554,"text":"is not done until your Auditor can explain"},{"start":234.554,"end":234.733,"text":"it."},{"start":235.091,"end":237.359,"text":"Then you redraw the map and try again."},{"start":239.317,"end":242.314,"text":"Sandoval's own project followed the same"},{"start":242.314,"end":242.753,"text":"logic."},{"start":243.192,"end":246.262,"text":"Analyzing two teachers' classrooms showed"},{"start":246.262,"end":249.333,"text":"productive argument where talk focused on"},{"start":249.333,"end":252.404,"text":"building consensus, so his team revised"},{"start":252.404,"end":254.89,"text":"the map to design the classroom's"},{"start":254.89,"end":257.668,"text":"discursive practice, its social and"},{"start":257.668,"end":258.838,"text":"epistemic norms."},{"start":260.773,"end":263.378,"text":"Three cautions come from Sandoval himself:"},{"start":263.378,"end":265.332,"text":"read the map as a process, not as"},{"start":265.332,"end":267.665,"text":"variables; different studies can test"},{"start":267.665,"end":270.27,"text":"different arrows; and the map does not yet"},{"start":270.27,"end":271.51800000000003,"text":"represent context well."},{"start":273.497,"end":275.989,"text":"Your turn: write one high level"},{"start":275.989,"end":279.02,"text":"conjecture, fill the embodiment slots your"},{"start":279.02,"end":281.849,"text":"design uses, name one process you could"},{"start":281.849,"end":284.813,"text":"see, one outcome you could measure, and"},{"start":284.813,"end":287.642,"text":"write both arrows as if, then sentences."},{"start":289.473,"end":291.479,"text":"For the discussion board, share your map"},{"start":291.479,"end":293.252,"text":"and mark the arrow you are least sure"},{"start":293.252,"end":293.531,"text":"about."},{"start":293.811,"end":295.77,"text":"Then say what evidence would convince you"},{"start":295.77,"end":296.423,"text":"that it holds."}]},"GcsN8Ozqvec":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.422,"text":"Two models come up whenever people design"},{"start":2.422,"end":4.67,"text":"motivating lessons or games: Thomas"},{"start":4.67,"end":6.479,"text":"Malone's theory of intrinsically"},{"start":6.479,"end":8.891,"text":"motivating instruction, and John Keller's"},{"start":8.891,"end":9.494,"text":"ARCS model."},{"start":9.823,"end":12.071,"text":"This video compares what each one is for."},{"start":13.92,"end":15.644,"text":"They answer different questions."},{"start":15.967,"end":18.176,"text":"Malone studied what makes computer games"},{"start":18.176,"end":20.223,"text":"fun, and turned it into a theory of"},{"start":20.223,"end":22.217,"text":"intrinsically motivating instruction."},{"start":23.16,"end":25.466,"text":"Keller asked how a designer can find and"},{"start":25.466,"end":27.828,"text":"fix a motivation problem in any course,"},{"start":27.828,"end":29.403,"text":"whether or not it is a game."},{"start":31.333,"end":34.117,"text":"Malone's theory has three ingredients:"},{"start":34.117,"end":36.964,"text":"challenge, built from goals with uncertain"},{"start":36.964,"end":39.875,"text":"outcomes; fantasy, which Malone argued"},{"start":39.875,"end":42.532,"text":"works better when it is tied to the skill"},{"start":42.532,"end":45.569,"text":"itself; and curiosity, sparked when what"},{"start":45.569,"end":47.214,"text":"you know feels incomplete."},{"start":48.083,"end":50.735,"text":"With Mark Lepper he later added control,"},{"start":50.735,"end":53.572,"text":"and three social motives: cooperation,"},{"start":53.572,"end":55.483,"text":"competition, and recognition."},{"start":57.313,"end":60.094,"text":"ARCS stands for attention, relevance,"},{"start":60.094,"end":62.146,"text":"confidence, and satisfaction."},{"start":62.983,"end":65.05,"text":"Keller grounded it in expectancy value"},{"start":65.05,"end":67.434,"text":"theory: we put in effort when something"},{"start":67.434,"end":69.501,"text":"matters to us and we expect to succeed."},{"start":69.819,"end":71.78,"text":"The model grew from work he began in"},{"start":71.78,"end":72.945,"text":"nineteen seventy nine."},{"start":74.773,"end":77.547,"text":"In Keller's later versions, each category"},{"start":77.547,"end":78.682,"text":"splits into three."},{"start":79.06,"end":81.582,"text":"Relevance, for example, covers goal"},{"start":81.582,"end":83.977,"text":"orientation, motive matching, and"},{"start":83.977,"end":84.73400000000001,"text":"familiarity."},{"start":85.112,"end":87.57,"text":"Note that satisfaction openly includes"},{"start":87.57,"end":88.705,"text":"extrinsic rewards."},{"start":90.65299999999999,"end":94.12100000000001,"text":"ARCS is also a design process: define,"},{"start":94.12100000000001,"end":97.363,"text":"design, develop, and evaluate, which"},{"start":97.363,"end":100.077,"text":"Keller describes as compatible with"},{"start":100.077,"end":102.791,"text":"typical instructional design models."},{"start":103.773,"end":106.19800000000001,"text":"And the first step is a check: is this"},{"start":106.19800000000001,"end":108.291,"text":"really a motivation problem, or are"},{"start":108.291,"end":109.614,"text":"learners missing skills?"},{"start":109.944,"end":111.763,"text":"ARCS is meant for the first case."},{"start":113.71000000000001,"end":114.82,"text":"Here is a toy audit."},{"start":115.154,"end":117.208,"text":"A twenty minute fractions lesson has"},{"start":117.208,"end":119.65100000000001,"text":"students serving pizza orders, like three"},{"start":119.65100000000001,"end":120.65,"text":"eighths pepperoni."},{"start":120.983,"end":123.371,"text":"Five learners rate each ARCS category from"},{"start":123.371,"end":124.037,"text":"one to five."},{"start":124.93,"end":126.174,"text":"Average each column."},{"start":126.547,"end":129.16,"text":"Attention and satisfaction are already at"},{"start":129.16,"end":129.47,"text":"four."},{"start":129.844,"end":132.643,"text":"Relevance averages two, and confidence two"},{"start":132.643,"end":133.327,"text":"point four."},{"start":134.21,"end":136.922,"text":"So against a target of four, relevance is"},{"start":136.922,"end":139.079,"text":"the biggest gap, then confidence."},{"start":139.448,"end":141.482,"text":"The game already grabs attention."},{"start":141.852,"end":144.255,"text":"Learners just do not see why fractions"},{"start":144.255,"end":146.72,"text":"matter, or feel unsure they can do it."},{"start":148.61,"end":150.965,"text":"An ARCS designer targets the gap that was"},{"start":150.965,"end":153.65699999999998,"text":"measured: use the class's own lunch orders"},{"start":153.65699999999998,"end":155.788,"text":"for relevance, and show the success"},{"start":155.788,"end":157.13400000000001,"text":"criteria for confidence."},{"start":158.01,"end":160.678,"text":"A Malone designer adds features: make the"},{"start":160.678,"end":163.232,"text":"fantasy intrinsic, so slicing the pizza is"},{"start":163.232,"end":165.787,"text":"the fraction skill, and add challenge with"},{"start":165.787,"end":167.489,"text":"hidden orders that get harder."},{"start":168.46,"end":170.73,"text":"Put simply, Malone tells you which fun"},{"start":170.73,"end":173,"text":"ingredients to add, and ARCS tells you"},{"start":173,"end":174.938,"text":"which one this audience is missing."},{"start":176.787,"end":178.035,"text":"You can see parallels."},{"start":178.375,"end":180.759,"text":"Malone's challenge sits close to Keller's"},{"start":180.759,"end":183.142,"text":"confidence, which calls for conquerable"},{"start":183.142,"end":185.468,"text":"challenge, and curiosity sits close to"},{"start":185.468,"end":186.376,"text":"inquiry arousal."},{"start":187.227,"end":188.85,"text":"But the difference matters."},{"start":189.21,"end":191.194,"text":"Malone describes features of fun"},{"start":191.194,"end":191.856,"text":"activities."},{"start":192.216,"end":194.26,"text":"ARCS is a procedure driven by the"},{"start":194.26,"end":196.845,"text":"audience, and it openly allows extrinsic"},{"start":196.845,"end":197.326,"text":"rewards."},{"start":199.32,"end":200.54,"text":"How strong is the evidence?"},{"start":200.811,"end":202.755,"text":"A meta analysis of thirty eight controlled"},{"start":202.755,"end":204.472,"text":"ARCS studies found an effect of point"},{"start":204.472,"end":206.325,"text":"seven four on achievement and point four"},{"start":206.325,"end":207.22899999999998,"text":"three on motivation."},{"start":208.06,"end":209.956,"text":"But the authors warn these numbers are"},{"start":209.956,"end":212.047,"text":"only as good as the primary studies, and"},{"start":212.047,"end":213.992,"text":"Keller's own early field tests measured"},{"start":213.992,"end":215.548,"text":"teachers' views, not learning."},{"start":217.46,"end":218.62,"text":"So use them together."},{"start":218.952,"end":220.996,"text":"Diagnose with ARCS to find what this"},{"start":220.996,"end":223.428,"text":"audience is missing, then borrow Malone's"},{"start":223.428,"end":225.804,"text":"features to fix it, and keep the fantasy"},{"start":225.804,"end":226.798,"text":"tied to the skill."},{"start":228.73,"end":231.118,"text":"For the discussion board, name the weakest"},{"start":231.118,"end":233.348,"text":"ARCS category in a lesson you know, and"},{"start":233.348,"end":235.312,"text":"one Malone feature that could fix it."}]},"GTUT49cgqQE":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.033,"text":"A design works beautifully in one"},{"start":2.033,"end":2.599,"text":"classroom."},{"start":2.939,"end":5.145,"text":"Then it goes to ten, and the results"},{"start":5.145,"end":5.598,"text":"scatter."},{"start":5.937,"end":8.426,"text":"This video explains why that happens, and"},{"start":8.426,"end":10.633,"text":"how implementation research studies it"},{"start":10.633,"end":11.821,"text":"instead of hiding it."},{"start":13.773,"end":14.988,"text":"Here is a toy example."},{"start":15.32,"end":17.639,"text":"Recipe Remix, a fractions activity with"},{"start":17.639,"end":20.18,"text":"Chef and Auditor roles, began in class A,"},{"start":20.18,"end":22.555,"text":"with research support, and the mean gain"},{"start":22.555,"end":24.322,"text":"there was two point four points."},{"start":25.323,"end":27.145,"text":"Now nine more classes try it."},{"start":27.522,"end":29.909,"text":"The gains range from point two to two"},{"start":29.909,"end":32.61,"text":"point six, and the average of all ten is"},{"start":32.61,"end":35.06,"text":"one point four three, well below the"},{"start":35.06,"end":35.436,"text":"pilot."},{"start":37.393,"end":40.176,"text":"Color the classes by one thing: did the"},{"start":40.176,"end":42.093,"text":"Auditor really ask for reasons?"},{"start":42.464,"end":45.184,"text":"Where the core was enacted, the mean gain"},{"start":45.184,"end":46.545,"text":"was two point one two."},{"start":46.916,"end":48.832,"text":"Where it was not, point four."},{"start":49.753,"end":51.664,"text":"This is an association, not proof."},{"start":51.983,"end":54.159,"text":"Teachers who kept the core may differ in"},{"start":54.159,"end":55.115,"text":"other ways, too."},{"start":57.043,"end":58.846,"text":"This is not a strange accident."},{"start":59.194,"end":61.52,"text":"William Penuel and colleagues note that"},{"start":61.52,"end":63.845,"text":"the effects of nearly all programs vary"},{"start":63.845,"end":66.055,"text":"significantly from setting to setting."},{"start":66.953,"end":69.125,"text":"They also recall an older finding:"},{"start":69.125,"end":71.405,"text":"teachers' adaptations in the classroom,"},{"start":71.405,"end":73.359,"text":"not policy makers' plans, largely"},{"start":73.359,"end":75.368,"text":"determine how effective a program is."},{"start":77.31,"end":79.263,"text":"Not all adaptation is the same."},{"start":79.64099999999999,"end":81.90899999999999,"text":"Class F swapped the strips for real"},{"start":81.90899999999999,"end":84.304,"text":"measuring cups, and still asked for"},{"start":84.304,"end":84.80799999999999,"text":"reasons."},{"start":85.186,"end":87.202,"text":"That is a productive adaptation."},{"start":88.08,"end":90.58500000000001,"text":"In class G, the teacher became the Auditor"},{"start":90.58500000000001,"end":92.755,"text":"and just marked answers right or wrong."},{"start":93.089,"end":95.42699999999999,"text":"The activity survived on paper, but the"},{"start":95.42699999999999,"end":96.206,"text":"core was gone."},{"start":97.16,"end":99.44800000000001,"text":"Ann Brown and Joseph Campione brought a"},{"start":99.44800000000001,"end":101.793,"text":"name for this into educational design,"},{"start":101.793,"end":104.36699999999999,"text":"crediting Ed Haertel: a lethal mutation."},{"start":105.21000000000001,"end":107.22399999999999,"text":"So the real question is not fidelity"},{"start":107.22399999999999,"end":108.20400000000001,"text":"versus adaptation."},{"start":108.531,"end":110.81700000000001,"text":"It is knowing which parts of a design are"},{"start":110.81700000000001,"end":112.613,"text":"core, and which parts can flex."},{"start":114.56700000000001,"end":116.82,"text":"Capacity is part of the design, too."},{"start":117.175,"end":119.487,"text":"When California reduced class sizes,"},{"start":119.487,"end":121.977,"text":"smaller classes raised achievement, but"},{"start":121.977,"end":124.29,"text":"hiring many inexperienced, not fully"},{"start":124.29,"end":126.661,"text":"certified teachers dampened the benefit."},{"start":128.587,"end":130.407,"text":"This is why Cynthia Coburn argued that"},{"start":130.407,"end":132.133,"text":"scale should mean more than counting"},{"start":132.133,"end":132.507,"text":"schools."},{"start":134.297,"end":136.34199999999998,"text":"She proposed four dimensions."},{"start":136.766,"end":139.869,"text":"Depth, change in beliefs and norms, not"},{"start":139.869,"end":140.927,"text":"just materials."},{"start":141.351,"end":144.313,"text":"Sustainability, change that lasts after"},{"start":144.313,"end":145.653,"text":"extra support ends."},{"start":146.677,"end":148.688,"text":"Spread, of the principles, including"},{"start":148.688,"end":149.816,"text":"within a single school."},{"start":150.11,"end":152.17000000000002,"text":"And a shift in ownership, so the reform"},{"start":152.17000000000002,"end":154.18099999999998,"text":"belongs to the teachers and schools that"},{"start":154.18099999999998,"end":154.622,"text":"carry it."},{"start":158.11,"end":160.372,"text":"Two research approaches were built for"},{"start":160.372,"end":160.662,"text":"this."},{"start":161.00900000000001,"end":163.155,"text":"Design based implementation research"},{"start":163.155,"end":165.591,"text":"treats implementation itself as something"},{"start":165.591,"end":167.736,"text":"to design and theorize, and builds"},{"start":167.736,"end":169.302,"text":"capacity to sustain change."},{"start":170.14,"end":172.737,"text":"Improvement science asks us to attend to"},{"start":172.737,"end":175.903,"text":"variability: not just what works, but what"},{"start":175.903,"end":178.183,"text":"works, for whom, and under what"},{"start":178.183,"end":178.88,"text":"conditions."},{"start":180.887,"end":183.077,"text":"So when you scale a design, study the"},{"start":183.077,"end":185.376,"text":"variation instead of averaging it away,"},{"start":185.376,"end":187.676,"text":"name your core components, redesign the"},{"start":187.676,"end":189.975,"text":"supports where the core broke, and plan"},{"start":189.975,"end":192.439,"text":"for depth, sustainability, spread, and"},{"start":192.439,"end":193.698,"text":"ownership from day one."},{"start":195.54,"end":197.593,"text":"For the discussion board, pick a design"},{"start":197.593,"end":198.912,"text":"you know and name its core."},{"start":199.206,"end":201.307,"text":"Then describe what a lethal mutation of it"},{"start":201.307,"end":203.067,"text":"would look like in a real classroom."}]},"Navj1yDN5-Q":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":5.762,"end":7.453,"text":"Put on a headset, and your room"},{"start":7.453,"end":8,"text":"disappears."},{"start":8.298,"end":9.989,"text":"You are standing inside a glowing"},{"start":9.989,"end":11.878,"text":"chemistry lab, and it feels amazing."},{"start":12.177,"end":14.265,"text":"But does feeling amazing mean you learned"},{"start":14.265,"end":14.514,"text":"more?"},{"start":16.775,"end":19.018,"text":"Meet two friends who study the same"},{"start":19.018,"end":20.389,"text":"virtual chemistry lab."},{"start":20.763,"end":22.32,"text":"Jordan works on a laptop."},{"start":22.694,"end":24.252,"text":"Riley wears a VR headset."},{"start":30.519,"end":32.268,"text":"Most people would bet on Riley."},{"start":32.607,"end":34.75,"text":"A real experiment tested exactly this"},{"start":34.75,"end":35.371,"text":"comparison."},{"start":37.289,"end":39.833,"text":"In twenty nineteen, Guido Makransky,"},{"start":39.833,"end":42.378,"text":"Thomas Terkildsen and Richard Mayer gave"},{"start":42.378,"end":44.798,"text":"fifty two university students the same"},{"start":44.798,"end":47.156,"text":"science lab simulation, either on a"},{"start":47.156,"end":49.266,"text":"desktop screen or in a VR headset."},{"start":51.375,"end":53.699,"text":"Here are the results, as effect sizes."},{"start":54.048,"end":56.604,"text":"Arrows to the right mean higher in VR;"},{"start":56.604,"end":58.696,"text":"arrows to the left mean lower in VR."},{"start":59.979,"end":61.104,"text":"First, presence."},{"start":61.479,"end":63.918,"text":"Students in VR felt far more like they"},{"start":63.918,"end":66.67,"text":"were really there, with an effect size of"},{"start":66.67,"end":67.67,"text":"one point three."},{"start":68.045,"end":69.233,"text":"That is very large."},{"start":72.57300000000001,"end":75.288,"text":"Presence is the felt sense of being inside"},{"start":75.288,"end":76.425,"text":"the virtual place."},{"start":76.803,"end":77.814,"text":"VR delivered it."},{"start":79.941,"end":81.445,"text":"Second, the learning test."},{"start":81.767,"end":84.13,"text":"The VR group scored lower, with an effect"},{"start":84.13,"end":86.17099999999999,"text":"size of zero point eight in the wrong"},{"start":86.17099999999999,"end":86.708,"text":"direction."},{"start":87.975,"end":89.451,"text":"Third, a brain measure."},{"start":89.805,"end":92.286,"text":"An E E G headband showed higher cognitive"},{"start":92.286,"end":94.707,"text":"load in VR, meaning working memory was"},{"start":94.707,"end":95.12,"text":"busier."},{"start":97.425,"end":100.158,"text":"The paper's title says it plainly: more"},{"start":100.158,"end":101.97999999999999,"text":"presence, but less learning."},{"start":105.509,"end":106.57300000000001,"text":"Why would this happen?"},{"start":106.863,"end":108.94200000000001,"text":"Picture working memory as a small backpack"},{"start":108.94200000000001,"end":110.344,"text":"you carry through the lesson."},{"start":110.63499999999999,"end":111.699,"text":"It only holds so much."},{"start":112.535,"end":114.53999999999999,"text":"On a desktop, the virtual world takes a"},{"start":114.53999999999999,"end":116.642,"text":"little space, which leaves plenty of room"},{"start":116.642,"end":117.358,"text":"for the lesson."},{"start":118.607,"end":121.201,"text":"In VR, the sights, the sounds and the new"},{"start":121.201,"end":122.555,"text":"controls take much more."},{"start":122.893,"end":125.036,"text":"The lesson gets squeezed into what is"},{"start":125.036,"end":125.318,"text":"left."},{"start":128.495,"end":130.275,"text":"It is a bit like trying to study for an"},{"start":130.275,"end":132.055,"text":"exam while you stand in the middle of a"},{"start":132.055,"end":132.768,"text":"busy theme park."},{"start":140.47899999999998,"end":141.236,"text":"Not at all."},{"start":141.648,"end":144.332,"text":"A meta analysis of forty eight studies"},{"start":144.332,"end":147.566,"text":"found that, on average, immersive VR has a"},{"start":147.566,"end":149.906,"text":"small positive effect on learning."},{"start":151.027,"end":153.258,"text":"But an average hides both wins and losses,"},{"start":153.258,"end":154.498,"text":"like the one we just saw."},{"start":154.796,"end":156.829,"text":"What decides which one you get is design."},{"start":159.589,"end":161.824,"text":"So how do we design for learning?"},{"start":162.231,"end":165.008,"text":"First, use VR where being there really"},{"start":165.008,"end":168.328,"text":"matters, such as space, scale, the body,"},{"start":168.328,"end":170.292,"text":"or places too risky to visit."},{"start":173.301,"end":175.734,"text":"Second, keep the virtual world calm when"},{"start":175.734,"end":178.167,"text":"the content is hard, so the scenery does"},{"start":178.167,"end":179.751,"text":"not compete with the lesson."},{"start":182.589,"end":184.285,"text":"Third, add a thinking task."},{"start":184.636,"end":186.917,"text":"Jocelyn Parong and Richard Mayer found"},{"start":186.917,"end":189.257,"text":"that asking learners to summarize after"},{"start":189.257,"end":191.597,"text":"each segment of a VR lesson helped them"},{"start":191.597,"end":191.948,"text":"learn."},{"start":194.852,"end":196.511,"text":"Back to our two friends."},{"start":196.926,"end":198.032,"text":"Riley felt more."},{"start":198.447,"end":199.82999999999998,"text":"Jordan learned more."},{"start":200.245,"end":202.457,"text":"Both things can be true at once."},{"start":203.48,"end":206.05,"text":"So remember: wow is a feeling, and"},{"start":206.05,"end":207.763,"text":"learning is a design result."},{"start":210.692,"end":212.39600000000002,"text":"These are the studies behind this video."}]},"LKY8wo6KoDw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.012,"text":"In part A, play became evidence."},{"start":2.345,"end":4.682,"text":"Part B shows how a Bayesian network turns"},{"start":4.682,"end":6.796,"text":"that evidence into beliefs about each"},{"start":6.796,"end":7.686,"text":"player's skills."},{"start":9.44,"end":11.441,"text":"Start with the Q matrix from part A."},{"start":11.774,"end":14.219,"text":"Each skill becomes a node at the top, and"},{"start":14.219,"end":16.109,"text":"each one in the matrix becomes an"},{"start":16.109,"end":18.554,"text":"observable node below, with an arrow from"},{"start":18.554,"end":19.777,"text":"the skill it measures."},{"start":20.82,"end":23.043,"text":"Skills can also depend on each other."},{"start":23.403,"end":25.866,"text":"Here, interpreting graphs makes causal"},{"start":25.866,"end":28.268,"text":"explanations more likely, so one more"},{"start":28.268,"end":29.29,"text":"arrow joins them."},{"start":30.08,"end":32.409,"text":"That picture, plus a probability table at"},{"start":32.409,"end":34.262,"text":"each node, is a Bayesian network."},{"start":36.243,"end":38.04,"text":"Each observable has a small table."},{"start":38.357,"end":40.629,"text":"A player who has mastered variable control"},{"start":40.629,"end":43.112,"text":"shows it eighty five percent of the time;"},{"start":43.112,"end":45.12,"text":"one who has not still shows it thirty"},{"start":45.12,"end":46.176,"text":"percent of the time."},{"start":46.983,"end":48.727,"text":"Those two errors have names."},{"start":49.101,"end":51.716,"text":"A slip is when a skilled player misses,"},{"start":51.716,"end":54.207,"text":"and a guess is when an unskilled player"},{"start":54.207,"end":56.76,"text":"gets lucky, like player B's lucky shot."},{"start":58.653,"end":60.172,"text":"Now watch one belief update."},{"start":60.498,"end":62.885,"text":"Before any play, we are fifty fifty about"},{"start":62.885,"end":64.838,"text":"whether player A controls variables."},{"start":65.703,"end":68.286,"text":"In level two, the evidence rule fires: one"},{"start":68.286,"end":69.164,"text":"slider at a time."},{"start":69.474,"end":71.695,"text":"Bayes' rule moves the belief to zero point"},{"start":71.695,"end":72.263,"text":"seven four."},{"start":77.383,"end":79.74,"text":"In level five it happens again, and the"},{"start":79.74,"end":81.929,"text":"belief rises to about zero point eight"},{"start":81.929,"end":82.21000000000001,"text":"nine."},{"start":82.547,"end":84.96000000000001,"text":"Evidence accumulates, like a detective's"},{"start":84.96000000000001,"end":85.297,"text":"notes."},{"start":87.07300000000001,"end":89.41,"text":"After all five levels, here is what the"},{"start":89.41,"end":90.355,"text":"network believes."},{"start":90.689,"end":92.97,"text":"Player A looks strong on all four skills."},{"start":93.923,"end":96.689,"text":"Player B is strong at reading graphs, but"},{"start":96.689,"end":99.518,"text":"weak at controlling variables, revising,"},{"start":99.518,"end":100.9,"text":"and explaining causes."},{"start":101.27799999999999,"end":103.60300000000001,"text":"Same three stars, a very different"},{"start":103.60300000000001,"end":104.106,"text":"profile."},{"start":106.02000000000001,"end":108.096,"text":"Where do numbers like zero point eight"},{"start":108.096,"end":110.012,"text":"five and zero point three come from?"},{"start":110.331,"end":112.513,"text":"With pilot data, a cognitive diagnosis"},{"start":112.513,"end":113.78999999999999,"text":"model can estimate them."},{"start":114.11,"end":116.345,"text":"Here we simulate two thousand players and"},{"start":116.345,"end":116.771,"text":"fit one."},{"start":117.67,"end":120.184,"text":"Most estimates land near the true values."},{"start":120.552,"end":122.944,"text":"But variable control and revision have"},{"start":122.944,"end":125.703,"text":"only two observables each in the Q matrix,"},{"start":125.703,"end":127.359,"text":"and their estimates wobble."},{"start":127.727,"end":129.812,"text":"Thin evidence gives shaky numbers."},{"start":130.77,"end":132.833,"text":"This also shows that cognitive diagnosis"},{"start":132.833,"end":134.795,"text":"models and Bayesian networks are close"},{"start":134.795,"end":135.298,"text":"relatives."},{"start":137.293,"end":139.125,"text":"Players also learn while they play."},{"start":139.44,"end":141.53300000000002,"text":"A dynamic Bayesian network carries each"},{"start":141.53300000000002,"end":143.889,"text":"belief from level to level, adding a small"},{"start":143.889,"end":145.459,"text":"chance of learning in between."},{"start":146.303,"end":148.602,"text":"Player A's belief climbs as the evidence"},{"start":148.602,"end":149.106,"text":"comes in."},{"start":149.442,"end":151.853,"text":"Player B's sinks, because each chance to"},{"start":151.853,"end":153.927,"text":"control variables goes by without it."},{"start":158.41,"end":160.667,"text":"The beliefs then drive the game."},{"start":161.09,"end":164.264,"text":"In a four process loop, the system selects"},{"start":164.264,"end":167.367,"text":"the next level, presents it, identifies"},{"start":167.367,"end":169.977,"text":"evidence, and accumulates it again."},{"start":170.94,"end":172.918,"text":"For player B, the weakest skill is causal"},{"start":172.918,"end":174.895,"text":"explanation, so the next level could be a"},{"start":174.895,"end":175.929,"text":"surprise that asks why."},{"start":176.199,"end":178.132,"text":"This is stealth assessment: measuring"},{"start":178.132,"end":179.3,"text":"without stopping the game."},{"start":182.167,"end":184.551,"text":"Before trusting these numbers, validate"},{"start":184.551,"end":186.992,"text":"the Q matrix, learn the tables from real"},{"start":186.992,"end":189.149,"text":"pilot data, compare with an outside"},{"start":189.149,"end":191.64600000000002,"text":"measure, and check fairness across groups."},{"start":193.597,"end":196.445,"text":"Here is the whole pipeline: claims shape"},{"start":196.445,"end":199.356,"text":"levels, the Q matrix links them to skills,"},{"start":199.356,"end":202.143,"text":"evidence rules turn logs into observables,"},{"start":202.143,"end":204.93,"text":"the network updates beliefs, and decisions"},{"start":204.93,"end":207.345,"text":"feed back into the game and its design."},{"start":208.177,"end":209.245,"text":"And our two players?"},{"start":209.566,"end":211.65,"text":"Same three stars, but very different"},{"start":211.65,"end":213.253,"text":"evidence about how they think."},{"start":213.573,"end":215.871,"text":"That is what a game can tell us, when it"},{"start":215.871,"end":217.046,"text":"is designed to listen."}]},"XC_5YE2YYoY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.04,"end":2.168,"text":"How can a game tell us what a learner"},{"start":2.168,"end":4.688,"text":"knows, without stopping the game to give a"},{"start":4.688,"end":4.968,"text":"test?"},{"start":5.304,"end":7.712,"text":"This is part one of a two part story about"},{"start":7.712,"end":8.944,"text":"game based assessment."},{"start":10.873,"end":13.084,"text":"Meet Launch Lab, a small physics game."},{"start":13.416,"end":16.125,"text":"Players set the angle, speed, and gravity,"},{"start":16.125,"end":17.562,"text":"and try to hit the target."},{"start":18.443,"end":20.749,"text":"Player A changes only the angle, misses"},{"start":20.749,"end":23.22,"text":"short, changes the angle again, and hits"},{"start":23.22,"end":23.824,"text":"the target."},{"start":26.753,"end":29.03,"text":"Player B changes all three sliders at"},{"start":29.03,"end":31.486,"text":"once, overshoots, changes everything"},{"start":31.486,"end":32.984,"text":"again, and hits it too."},{"start":39.143,"end":40.66,"text":"Same stars, same score."},{"start":41.025,"end":43.634,"text":"But only player A tested one variable at a"},{"start":43.634,"end":43.937,"text":"time."},{"start":44.302,"end":46.668,"text":"Game based assessment is about reading"},{"start":46.668,"end":47.639,"text":"that difference."},{"start":49.653,"end":52.191,"text":"The design idea behind this is evidence"},{"start":52.191,"end":54.919,"text":"centered design, or E C D, from Robert"},{"start":54.919,"end":56.378,"text":"Mislevy and colleagues."},{"start":56.759,"end":59.614,"text":"It starts with a claim, asks what evidence"},{"start":59.614,"end":62.405,"text":"would support it, and only then designs a"},{"start":62.405,"end":62.723,"text":"task."},{"start":63.723,"end":65.394,"text":"A road test works the same way."},{"start":65.717,"end":67.98,"text":"To claim someone drives safely, we look"},{"start":67.98,"end":70.35,"text":"for mirror checks before lane changes, so"},{"start":70.35,"end":72.28999999999999,"text":"the route must include lane changes."},{"start":73.253,"end":75.627,"text":"So an assessment is an argument, from what"},{"start":75.627,"end":77.737,"text":"learners do to what we claim about them."},{"start":79.687,"end":82.212,"text":"E C D organizes this into three linked"},{"start":82.212,"end":85.255,"text":"models: a competency model, an evidence"},{"start":85.255,"end":86.938,"text":"model, and a task model."},{"start":87.81700000000001,"end":90.481,"text":"In Launch Lab, the competency model is"},{"start":90.481,"end":93.729,"text":"causal reasoning, broken into four skills:"},{"start":93.729,"end":96.523,"text":"controlling variables, revising ideas,"},{"start":96.523,"end":98.99199999999999,"text":"interpreting graphs, and explaining"},{"start":98.99199999999999,"end":99.447,"text":"causes."},{"start":100.34700000000001,"end":102.672,"text":"These are latent skills: we cannot see"},{"start":102.672,"end":104.89099999999999,"text":"them, only infer them from what players"},{"start":104.89099999999999,"end":105.05,"text":"do."},{"start":106.94,"end":109.055,"text":"The task model shapes the levels."},{"start":109.44,"end":112.068,"text":"Each level has features chosen to make a"},{"start":112.068,"end":114.375,"text":"particular kind of thinking visible."},{"start":115.39,"end":118.017,"text":"For example, level four deliberately"},{"start":118.017,"end":120.712,"text":"produces a surprising result, because"},{"start":120.712,"end":123.339,"text":"revising an idea only shows up after a"},{"start":123.339,"end":123.946,"text":"surprise."},{"start":125.997,"end":128.181,"text":"The bridge between levels and skills is"},{"start":128.181,"end":128.891,"text":"the Q matrix."},{"start":129.219,"end":131.731,"text":"Each row is a level, each column a skill,"},{"start":131.731,"end":133.971,"text":"and a one means the level gives evidence"},{"start":133.971,"end":134.899,"text":"about that skill."},{"start":135.827,"end":138.406,"text":"Level four, for instance, informs three"},{"start":138.406,"end":140.692,"text":"skills at once: revision, graph"},{"start":140.692,"end":143.095,"text":"interpretation, and causal explanation."},{"start":148.267,"end":148.423,"text":"No."},{"start":148.736,"end":150.821,"text":"Its variable control cell is zero, so"},{"start":150.821,"end":152.803,"text":"nothing a player does there counts as"},{"start":152.803,"end":154.054,"text":"evidence for that skill."},{"start":154.857,"end":157.091,"text":"A Q matrix is a claim in itself, so it"},{"start":157.091,"end":158.017,"text":"must be defended."},{"start":158.344,"end":160.633,"text":"Turning on cells without a reason makes a"},{"start":160.633,"end":162.976,"text":"diagnosis look more precise than it really"},{"start":162.976,"end":163.14,"text":"is."},{"start":165.083,"end":166.53,"text":"Now the evidence model."},{"start":166.90699999999998,"end":169.674,"text":"Underneath the game, every action becomes"},{"start":169.674,"end":172.379,"text":"a row in a log: predictions, slider"},{"start":172.379,"end":174.768,"text":"changes, runs, graph views, and"},{"start":174.768,"end":175.586,"text":"explanations."},{"start":176.383,"end":178.623,"text":"Evidence rules turn those rows into a few"},{"start":178.623,"end":179.903,"text":"meaningful observations."},{"start":180.223,"end":182.41,"text":"Changing only one slider before each run"},{"start":182.41,"end":184.383,"text":"becomes evidence of variable control."},{"start":186.323,"end":188.464,"text":"Each one in the Q matrix becomes one such"},{"start":188.464,"end":189.024,"text":"observable."},{"start":189.33,"end":191.47,"text":"Recording clicks without rules like these"},{"start":191.47,"end":193.814,"text":"is just logging; the rules are what make"},{"start":193.814,"end":194.528,"text":"it assessment."},{"start":196.53,"end":199.61599999999999,"text":"So far we have claims, tasks, a Q matrix,"},{"start":199.61599999999999,"end":200.837,"text":"and evidence rules."},{"start":201.223,"end":204.051,"text":"In part B, a Bayesian network turns those"},{"start":204.051,"end":206.623,"text":"observations into updated beliefs about"},{"start":206.623,"end":207.394,"text":"each player."}]},"Cn2KU6ooubI":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.055,"text":"Design based research almost always"},{"start":2.055,"end":3.027,"text":"involves partners."},{"start":3.351,"end":5.62,"text":"Two words describe that partnership, co"},{"start":5.62,"end":7.997,"text":"design and participatory design, and they"},{"start":7.997,"end":10.211,"text":"are often used as if they meant the same"},{"start":10.211,"end":12.156,"text":"thing, although they do not quite."},{"start":14.16,"end":16.484,"text":"Picture the team designing an A I feedback"},{"start":16.484,"end":17.889,"text":"tool for a writing course."},{"start":18.213,"end":20.644,"text":"Who sits at the design table, and who gets"},{"start":20.644,"end":22.536,"text":"to decide what the problem even is?"},{"start":24.56,"end":27.018,"text":"In one version, teachers join facilitated"},{"start":27.018,"end":29.196,"text":"sessions in defined roles to shape the"},{"start":29.196,"end":29.475,"text":"tool."},{"start":29.81,"end":32.324,"text":"In another, students and community members"},{"start":32.324,"end":34.446,"text":"help decide the problem itself, who"},{"start":34.446,"end":36.345,"text":"benefits, and who owns the data."},{"start":42.36,"end":44.694,"text":"Scenario A is typical of co design, and"},{"start":44.694,"end":46.639,"text":"scenario B of participatory design."},{"start":46.973,"end":49.418,"text":"The difference is less about who attends,"},{"start":49.418,"end":51.641,"text":"and more about who holds power over the"},{"start":51.641,"end":52.197,"text":"decisions."},{"start":54,"end":56.295,"text":"Participatory design began in Scandinavian"},{"start":56.295,"end":58.164,"text":"workplace projects of the nineteen"},{"start":58.164,"end":60.513,"text":"seventies and eighties, where workers and"},{"start":60.513,"end":62.595,"text":"their unions helped shape the computer"},{"start":62.595,"end":64.57,"text":"systems that would change their jobs."},{"start":65.56,"end":67.887,"text":"Its core commitment is political as well"},{"start":67.887,"end":70.554,"text":"as practical: people affected by a design"},{"start":70.554,"end":72.825,"text":"should have a real say in it, through"},{"start":72.825,"end":74.981,"text":"mutual learning and shared power over"},{"start":74.981,"end":76.059,"text":"goals and outcomes."},{"start":78.01,"end":80.202,"text":"Co design is a broader term from design"},{"start":80.202,"end":80.696,"text":"practice."},{"start":81.025,"end":83.327,"text":"Elizabeth Sanders and Pieter Jan Stappers"},{"start":83.327,"end":85.574,"text":"describe it as the collective creativity"},{"start":85.574,"end":87.711,"text":"of designers and people not trained in"},{"start":87.711,"end":89.191,"text":"design, working together."},{"start":90.11,"end":93.069,"text":"In education, Jeremy Roschelle, William"},{"start":93.069,"end":96.02799999999999,"text":"Penuel, and Nicole Shechtman described co"},{"start":96.02799999999999,"end":99.055,"text":"design as a highly facilitated, team based"},{"start":99.055,"end":102.283,"text":"process, where teachers, researchers, and"},{"start":102.283,"end":104.70400000000001,"text":"developers work in defined roles to"},{"start":104.70400000000001,"end":107.327,"text":"design, prototype, and evaluate an"},{"start":107.327,"end":108.066,"text":"innovation."},{"start":109.07,"end":111.294,"text":"The emphasis here is fit to real"},{"start":111.294,"end":113.652,"text":"classrooms, drawing on teachers'"},{"start":113.652,"end":116.41499999999999,"text":"expertise, rather than a commitment to"},{"start":116.41499999999999,"end":117.696,"text":"redistribute power."},{"start":119.61,"end":121.56,"text":"It helps to picture participation as a"},{"start":121.56,"end":123.26,"text":"ladder, rather than a yes or no."},{"start":125.05,"end":127.285,"text":"Allison Druin described four roles"},{"start":127.285,"end":130.351,"text":"children can play in designing technology:"},{"start":130.351,"end":133.033,"text":"user, tester, informant, and design"},{"start":133.033,"end":135.907,"text":"partner, each with more influence than the"},{"start":135.907,"end":136.227,"text":"last."},{"start":137.14,"end":139.394,"text":"Co design usually sits from tester to"},{"start":139.394,"end":140.284,"text":"design partner."},{"start":140.64,"end":143.309,"text":"Participatory design aims for the top, and"},{"start":143.309,"end":145.86,"text":"adds a real say over goals and outcomes,"},{"start":145.86,"end":147.224,"text":"not just over features."},{"start":149.207,"end":152.454,"text":"Side by side, co design grew from design"},{"start":152.454,"end":154.796,"text":"practice and research practice"},{"start":154.796,"end":158.04399999999998,"text":"partnerships, and values fit to practice."},{"start":158.497,"end":161.594,"text":"Participatory design grew from workplace"},{"start":161.594,"end":164.69,"text":"democracy, and values voice and shared"},{"start":164.69,"end":165.143,"text":"power."},{"start":166.117,"end":168.41,"text":"The sharpest difference is who sets the"},{"start":168.41,"end":168.754,"text":"goals."},{"start":169.098,"end":171.793,"text":"Each also has its own risk: co design can"},{"start":171.793,"end":174.144,"text":"become consultation that only looks like"},{"start":174.144,"end":176.667,"text":"partnership, and participatory design can"},{"start":176.667,"end":178.273,"text":"be slow and hard to sustain."},{"start":180.21,"end":182.493,"text":"Inside design based research, the"},{"start":182.493,"end":184.775,"text":"participatory tradition shows up as"},{"start":184.775,"end":187.629,"text":"participatory design research, which Megan"},{"start":187.629,"end":190.038,"text":"Bang and Shirin Vossoughi describe as"},{"start":190.038,"end":192.955,"text":"attending to power, history, and who gets"},{"start":192.955,"end":194.16,"text":"to define learning."},{"start":195.13,"end":197.464,"text":"Whichever label you use, report it"},{"start":197.464,"end":200.493,"text":"honestly by answering three questions: who"},{"start":200.493,"end":203.269,"text":"defined the problem, who could change the"},{"start":203.269,"end":206.108,"text":"design and the goals, and who benefits and"},{"start":206.108,"end":206.99099999999999,"text":"owns the data."},{"start":208.897,"end":211.101,"text":"For the discussion board, find a study"},{"start":211.101,"end":212.768,"text":"that says it used co design or"},{"start":212.768,"end":215.133,"text":"participatory design, and decide where on"},{"start":215.133,"end":217.552,"text":"the ladder its partners really were, based"},{"start":217.552,"end":219.004,"text":"on what the authors report."}]},"pR--9zWzm30":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.03,"text":"Learning sciences and the science of"},{"start":2.03,"end":4.249,"text":"learning sound almost the same, but they"},{"start":4.249,"end":6.313,"text":"grew from different communities and ask"},{"start":6.313,"end":7.81,"text":"different kinds of questions."},{"start":8.12,"end":10.287,"text":"This video traces how each one evolved,"},{"start":10.287,"end":11.99,"text":"and why one of them ends in an s."},{"start":13.913,"end":15.871,"text":"Imagine two researchers who both care"},{"start":15.871,"end":17.674,"text":"about how children learn fractions."},{"start":18.533,"end":20.658,"text":"One asks whether spacing out practice"},{"start":20.658,"end":22.28,"text":"improves recall a week later."},{"start":22.616,"end":24.965,"text":"The other asks how a redesigned classroom"},{"start":24.965,"end":27.146,"text":"activity changes the way a whole class"},{"start":27.146,"end":28.488,"text":"reasons over a semester."},{"start":33.633,"end":35.499,"text":"The first question is typical of the"},{"start":35.499,"end":37.769,"text":"science of learning, and the second of the"},{"start":37.769,"end":38.676,"text":"learning sciences."},{"start":38.979,"end":41.097,"text":"To see why, it helps to follow how each"},{"start":41.097,"end":41.551,"text":"one grew."},{"start":43.407,"end":45.399,"text":"The learning sciences took shape around"},{"start":45.399,"end":47.541,"text":"nineteen ninety one, when the Journal of"},{"start":47.541,"end":49.335,"text":"the Learning Sciences and the first"},{"start":49.335,"end":51.178,"text":"international conference appeared,"},{"start":51.178,"end":52.722,"text":"building on a new institute at"},{"start":52.722,"end":53.918,"text":"Northwestern University."},{"start":54.817,"end":56.821,"text":"Its founders came largely from cognitive"},{"start":56.821,"end":58.923,"text":"science and artificial intelligence, but"},{"start":58.923,"end":60.781,"text":"they wanted to study learning in real"},{"start":60.781,"end":62.932,"text":"settings, and to learn by designing tools"},{"start":62.932,"end":63.763,"text":"and environments."},{"start":64.687,"end":66.687,"text":"In two thousand two, the International"},{"start":66.687,"end":68.687,"text":"Society of the Learning Sciences brought"},{"start":68.687,"end":70.833,"text":"the conferences and the journal together,"},{"start":70.833,"end":72.589,"text":"and in two thousand six a Cambridge"},{"start":72.589,"end":74.394,"text":"handbook gave the field a shared map."},{"start":76.337,"end":77.15,"text":"So why the s?"},{"start":77.525,"end":80.02799999999999,"text":"The name is plural because the field is"},{"start":80.02799999999999,"end":82.906,"text":"plural: cognitive science, educational"},{"start":82.906,"end":85.033,"text":"psychology, computer science,"},{"start":85.033,"end":87.911,"text":"anthropology, and more, each bringing its"},{"start":87.911,"end":88.661,"text":"own methods."},{"start":89.517,"end":91.589,"text":"Read the plural as a statement about"},{"start":91.589,"end":93.99799999999999,"text":"method: no single discipline owns the"},{"start":93.99799999999999,"end":95.175,"text":"question of learning."},{"start":95.511,"end":97.807,"text":"That is also why you will often hear the"},{"start":97.807,"end":100.21600000000001,"text":"learning sciences is, a plural name used"},{"start":100.21600000000001,"end":101.001,"text":"for one field."},{"start":102.987,"end":105.18299999999999,"text":"The science of learning grew along a"},{"start":105.18299999999999,"end":106.074,"text":"different path."},{"start":106.43,"end":108.686,"text":"In two thousand three, the National"},{"start":108.686,"end":111.06,"text":"Science Foundation announced Science of"},{"start":111.06,"end":113.672,"text":"Learning Centers, large centers that were"},{"start":113.672,"end":115.69,"text":"first funded in two thousand four."},{"start":116.547,"end":119.025,"text":"In two thousand nine, Andrew Meltzoff,"},{"start":119.025,"end":121.331,"text":"Patricia Kuhl, Javier Movellan, and"},{"start":121.331,"end":123.809,"text":"Terrence Sejnowski described a new science"},{"start":123.809,"end":126.172,"text":"of learning in the journal Science:"},{"start":126.172,"end":128.535,"text":"learning is computational, learning is"},{"start":128.535,"end":130.783,"text":"social, and it is supported by brain"},{"start":130.783,"end":133.031,"text":"circuits linking perception and action."},{"start":133.987,"end":136.007,"text":"Here the singular signals a goal of"},{"start":136.007,"end":138.308,"text":"convergence: several fields, from"},{"start":138.308,"end":140.497,"text":"psychology to neuroscience and machine"},{"start":140.497,"end":142.85399999999998,"text":"learning, working toward one account of"},{"start":142.85399999999998,"end":143.92000000000002,"text":"how learning works."},{"start":144.777,"end":147.673,"text":"For teachers, this tradition often arrives"},{"start":147.673,"end":150.569,"text":"as principles, like retrieval practice and"},{"start":150.569,"end":153.401,"text":"spacing, summarized in guides such as the"},{"start":153.401,"end":156.105,"text":"Deans for Impact report, The Science of"},{"start":156.105,"end":158.55,"text":"Learning, from two thousand fifteen."},{"start":160.453,"end":162.548,"text":"Put side by side, the science of learning"},{"start":162.548,"end":164.547,"text":"asks how learning works, mostly through"},{"start":164.547,"end":166.689,"text":"controlled experiments, while the learning"},{"start":166.689,"end":168.641,"text":"sciences ask how to make learning happen"},{"start":168.641,"end":170.688,"text":"in a real setting, mostly through design"},{"start":170.688,"end":171.688,"text":"and study in context."},{"start":172.583,"end":174.945,"text":"The science of learning usually studies"},{"start":174.945,"end":177.13,"text":"the individual mind and brain, and"},{"start":177.13,"end":178.784,"text":"produces general principles."},{"start":179.138,"end":181.5,"text":"The learning sciences study people with"},{"start":181.5,"end":184.275,"text":"tools, in groups and settings, and produce"},{"start":184.275,"end":186.519,"text":"designs with theories tied to context."},{"start":187.473,"end":188.903,"text":"Each one has a blind spot."},{"start":189.232,"end":191.211,"text":"A lab principle can fail in a noisy"},{"start":191.211,"end":193.575,"text":"classroom, and a classroom design can be"},{"start":193.575,"end":195.664,"text":"hard to generalize beyond the setting"},{"start":195.664,"end":196.434,"text":"where it grew."},{"start":198.387,"end":200.309,"text":"In practice the two traditions meet more"},{"start":200.309,"end":202.325,"text":"and more, and some of the best work sits"},{"start":202.325,"end":203.215,"text":"right between them."},{"start":204.977,"end":207.475,"text":"The Pittsburgh Science of Learning Center,"},{"start":207.475,"end":209.862,"text":"led by Kenneth Koedinger, ran controlled"},{"start":209.862,"end":212.305,"text":"experiments inside real courses, which it"},{"start":212.305,"end":213.804,"text":"called in vivo experiments."},{"start":214.90699999999998,"end":217.535,"text":"Another center, LIFE, studied learning in"},{"start":217.535,"end":219.877,"text":"informal and formal environments, from"},{"start":219.877,"end":221.534,"text":"homes and museums to schools."},{"start":222.517,"end":224.418,"text":"So a principle from the lab can become a"},{"start":224.418,"end":226.36599999999999,"text":"design conjecture in a classroom, and a"},{"start":226.36599999999999,"end":228.314,"text":"pattern noticed in a classroom can become"},{"start":228.314,"end":229.798,"text":"a hypothesis to test in the lab."},{"start":230.667,"end":233.56,"text":"For our two fraction researchers, that"},{"start":233.56,"end":236.382,"text":"means the spacing study could shape the"},{"start":236.382,"end":239.275,"text":"pizza activity, and the pizza activity"},{"start":239.275,"end":241.533,"text":"could reveal when spacing helps."},{"start":243.53,"end":245.552,"text":"For the discussion board, pick one claim"},{"start":245.552,"end":246.728,"text":"from this week's reading."},{"start":247.01,"end":249.032,"text":"Decide whether its evidence comes from the"},{"start":249.032,"end":250.725,"text":"science of learning or the learning"},{"start":250.725,"end":252.841,"text":"sciences, and ask what the other tradition"},{"start":252.841,"end":254.628,"text":"would want to see before believing it."}]},"NdaVj7XmiEU":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.458,"text":"What does a design based research project"},{"start":2.458,"end":4.963,"text":"actually look like, from the first meeting"},{"start":4.963,"end":6.021,"text":"to the final paper?"},{"start":6.355,"end":8.582,"text":"This video walks through the journey,"},{"start":8.582,"end":10.976,"text":"stage by stage, with one running example."},{"start":12.86,"end":15.636,"text":"Most accounts share five broad stages:"},{"start":15.636,"end":17.781,"text":"ground the problem, prepare the"},{"start":17.781,"end":20.684,"text":"experiment, run design cycles, analyze in"},{"start":20.684,"end":23.081,"text":"retrospect, and report and redesign."},{"start":23.97,"end":26.671,"text":"The arrow back matters: each report feeds"},{"start":26.671,"end":27.533,"text":"the next cycle."},{"start":27.878,"end":30.291,"text":"Our example is an A I feedback tool for a"},{"start":30.291,"end":31.785,"text":"first year writing course."},{"start":35.893,"end":37.544,"text":"Stage one grounds the problem."},{"start":37.874,"end":40.571,"text":"You meet partners, observe, and interview,"},{"start":40.571,"end":42.717,"text":"and read the research, to learn what"},{"start":42.717,"end":44.643,"text":"actually happens to feedback today."},{"start":45.543,"end":47.489,"text":"You leave with a problem of practice"},{"start":47.489,"end":49.803,"text":"stated together with partners: here,"},{"start":49.803,"end":51.96,"text":"students read feedback but rarely revise"},{"start":51.96,"end":52.328,"text":"deeply."},{"start":54.207,"end":56.031,"text":"Stage two prepares the experiment."},{"start":56.353,"end":58.768,"text":"You set learning goals, describe students'"},{"start":58.768,"end":61.021,"text":"starting points, and write a high level"},{"start":61.021,"end":63.704,"text":"conjecture: feedback that asks a question,"},{"start":63.704,"end":66.012,"text":"instead of giving a fix, leads to deeper"},{"start":66.012,"end":66.495,"text":"revision."},{"start":67.337,"end":69.248,"text":"William Sandoval's conjecture map makes"},{"start":69.248,"end":71.35,"text":"this testable: the design's embodiment"},{"start":71.35,"end":73.404,"text":"should produce mediating processes you can"},{"start":73.404,"end":75.553,"text":"observe, which should lead to the outcomes"},{"start":75.553,"end":76.27,"text":"you care about."},{"start":77.247,"end":79.906,"text":"You also plan the data that will show each"},{"start":79.906,"end":82.751,"text":"arrow, such as drafts, tool logs, class"},{"start":82.751,"end":84.236,"text":"video, and interviews."},{"start":86.32300000000001,"end":88.557,"text":"Stage three runs the design in a real"},{"start":88.557,"end":88.968,"text":"course."},{"start":89.321,"end":91.907,"text":"Each full enactment is a macro cycle, and"},{"start":91.907,"end":94.435,"text":"inside it run many mini cycles of debriefs"},{"start":94.435,"end":95.61099999999999,"text":"and small revisions."},{"start":96.60300000000001,"end":98.697,"text":"Keep a design log of every change and why"},{"start":98.697,"end":100.441,"text":"you made it, because the changes"},{"start":100.441,"end":102.485,"text":"themselves are data about how the design"},{"start":102.485,"end":102.78399999999999,"text":"works."},{"start":104.843,"end":105.965,"text":"Stage four steps back."},{"start":106.27199999999999,"end":108.51599999999999,"text":"After the enactment ends, you analyze the"},{"start":108.51599999999999,"end":110.607,"text":"whole body of data systematically, not"},{"start":110.607,"end":112.137,"text":"just the moments you remember."},{"start":114.063,"end":116.47399999999999,"text":"You test each arrow of the conjecture map."},{"start":116.818,"end":119.458,"text":"In our example, students did write plans,"},{"start":119.458,"end":121.811,"text":"but deeper revision followed only when a"},{"start":121.811,"end":124.05,"text":"plan named a specific change, so the"},{"start":124.05,"end":125.829,"text":"conjecture itself gets revised."},{"start":129.407,"end":132.13400000000001,"text":"Stage five reports what was learned: a"},{"start":132.13400000000001,"end":134.737,"text":"humble theory of how the design worked,"},{"start":134.737,"end":137.34,"text":"design principles others can try, and a"},{"start":137.34,"end":139.385,"text":"better design for the next cycle."},{"start":140.347,"end":142.60399999999998,"text":"To be trusted, the report needs a clear"},{"start":142.60399999999998,"end":144.538,"text":"design narrative and claims tied to"},{"start":144.538,"end":146.956,"text":"evidence, and it generalizes by explaining"},{"start":146.956,"end":149.375,"text":"why the design worked, so others can judge"},{"start":149.375,"end":150.664,"text":"where it might transfer."},{"start":152.587,"end":154.81799999999998,"text":"For the discussion board, write a high"},{"start":154.81799999999998,"end":156.941,"text":"level conjecture for a project of your"},{"start":156.941,"end":159.391,"text":"own, sketch its conjecture map, and name"},{"start":159.391,"end":161.35,"text":"the data that would show each arrow."}]},"XN29cK9FYMY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.747,"text":"Design based research, educational design"},{"start":2.747,"end":5.075,"text":"research, and design and development"},{"start":5.075,"end":7.523,"text":"research all study learning by designing"},{"start":7.523,"end":8.12,"text":"something."},{"start":8.478,"end":10.866,"text":"This video compares where each one came"},{"start":10.866,"end":13.254,"text":"from, what it aims for, and what it"},{"start":13.254,"end":13.792,"text":"produces."},{"start":15.583,"end":17.607,"text":"Imagine a team building an A I feedback"},{"start":17.607,"end":19.48,"text":"tool for a first year writing course."},{"start":20.523,"end":22.746,"text":"They could ask how feedback timing shapes"},{"start":22.746,"end":24.809,"text":"revision, what design works in these"},{"start":24.809,"end":26.979,"text":"courses, or whether their design model"},{"start":26.979,"end":28.196,"text":"produced a usable tool."},{"start":33.333,"end":35.586,"text":"Roughly, the first leans toward design"},{"start":35.586,"end":37.563,"text":"based research, the second toward"},{"start":37.563,"end":40.036,"text":"educational design research, and the third"},{"start":40.036,"end":42.178,"text":"toward design and development research."},{"start":42.508,"end":44.925,"text":"All three share a core, but their centers"},{"start":44.925,"end":45.914,"text":"of gravity differ."},{"start":47.743,"end":50.018,"text":"Design based research grew in the learning"},{"start":50.018,"end":51.923,"text":"sciences, from Ann Brown's design"},{"start":51.923,"end":54.198,"text":"experiments and Allan Collins's call for a"},{"start":54.198,"end":56.261,"text":"design science of education, and was"},{"start":56.261,"end":58.43,"text":"popularized by the Design Based Research"},{"start":58.43,"end":60.176,"text":"Collective in two thousand three."},{"start":60.943,"end":62.746,"text":"Its hallmark is iteration in real"},{"start":62.746,"end":65.132,"text":"classrooms, where each version of a design"},{"start":65.132,"end":67.517,"text":"tests a conjecture about learning, and the"},{"start":67.517,"end":69.691,"text":"main contribution is a theory of how and"},{"start":69.691,"end":71.175,"text":"why learning happened there."},{"start":72.053,"end":73.878,"text":"Paul Cobb and colleagues called these"},{"start":73.878,"end":75.99,"text":"humble theories, because they are tied to"},{"start":75.99,"end":77.67099999999999,"text":"a domain and a setting rather than"},{"start":77.67099999999999,"end":79.015,"text":"claiming to hold everywhere."},{"start":80.953,"end":83,"text":"Educational design research is often used"},{"start":83,"end":85.04599999999999,"text":"as an umbrella term for this whole family."},{"start":85.339,"end":87.385,"text":"Susan McKenney and Thomas Reeves describe"},{"start":87.385,"end":89.383,"text":"it as solving a real problem in practice"},{"start":89.383,"end":91.381,"text":"while producing knowledge others can use."},{"start":92.283,"end":94.875,"text":"Its generic model has four phases, from"},{"start":94.875,"end":97.529,"text":"analysis and exploration to implementation"},{"start":97.529,"end":100.306,"text":"and spread, and it aims for two outputs at"},{"start":100.306,"end":103.083,"text":"once: an intervention that works, and"},{"start":103.083,"end":105.737,"text":"theoretical understanding, often written"},{"start":105.737,"end":107.033,"text":"as design principles."},{"start":110.55,"end":112.987,"text":"Design and development research comes from"},{"start":112.987,"end":115.02799999999999,"text":"instructional design and technology."},{"start":115.368,"end":117.805,"text":"Rita Richey and James Klein describe it as"},{"start":117.805,"end":119.733,"text":"the systematic study of design,"},{"start":119.733,"end":122,"text":"development, and evaluation processes."},{"start":122.95,"end":125.809,"text":"They distinguish two types: product and"},{"start":125.809,"end":128.731,"text":"tool research, which studies one product,"},{"start":128.731,"end":131.526,"text":"program, or tool, and model research,"},{"start":131.526,"end":134.13,"text":"which builds or validates a design model"},{"start":134.13,"end":134.829,"text":"or process."},{"start":135.92,"end":138.23,"text":"Here the knowledge produced is mainly"},{"start":138.23,"end":140.845,"text":"about designing and developing instruction"},{"start":140.845,"end":143.459,"text":"itself, so methods like expert review,"},{"start":143.459,"end":145.77,"text":"case studies, and Delphi panels are"},{"start":145.77,"end":146.195,"text":"common."},{"start":148.097,"end":150.769,"text":"Side by side, the differences are mostly"},{"start":150.769,"end":153.566,"text":"differences of emphasis: where each one"},{"start":153.566,"end":156.176,"text":"grew up, and what it treats as the main"},{"start":156.176,"end":156.984,"text":"contribution."},{"start":157.977,"end":160.21699999999998,"text":"Design based research puts a theory of"},{"start":160.21699999999998,"end":161.079,"text":"learning first."},{"start":161.424,"end":163.895,"text":"Educational design research puts a working"},{"start":163.895,"end":166.078,"text":"solution plus design principles first."},{"start":166.423,"end":168.779,"text":"Design and development research puts the"},{"start":168.779,"end":170.962,"text":"design process and its products first."},{"start":171.827,"end":174.482,"text":"What they share matters just as much:"},{"start":174.482,"end":177.26,"text":"iteration, real settings, design treated"},{"start":177.26,"end":179.236,"text":"as inquiry, and mixed methods."},{"start":181.397,"end":182.538,"text":"So how do you choose?"},{"start":182.864,"end":185.2,"text":"Ask what your main contribution will be,"},{"start":185.2,"end":186.831,"text":"and let that decide the frame."},{"start":188.777,"end":191.307,"text":"If it is a claim about how people learn,"},{"start":191.307,"end":192.897,"text":"design based research fits."},{"start":193.25,"end":195.722,"text":"If it is a solution to a practice problem"},{"start":195.722,"end":198.135,"text":"and its principles, educational design"},{"start":198.135,"end":198.959,"text":"research fits."},{"start":199.312,"end":202.196,"text":"If it is a design model, process, or tool,"},{"start":202.196,"end":204.374,"text":"design and development research fits."},{"start":205.387,"end":207.615,"text":"Whichever you choose, avoid the common"},{"start":207.615,"end":209.626,"text":"trap of only reporting that a design"},{"start":209.626,"end":210.006,"text":"worked."},{"start":210.332,"end":212.234,"text":"Design research also says what was"},{"start":212.234,"end":213.811,"text":"learned, and why it worked."},{"start":215.773,"end":218.129,"text":"For the discussion board, take one project"},{"start":218.129,"end":220.222,"text":"idea of your own and write its research"},{"start":220.222,"end":221.269,"text":"question three ways."},{"start":221.583,"end":223.46699999999998,"text":"Then decide which version you would"},{"start":223.46699999999998,"end":225.299,"text":"actually defend, and explain why."}]},"A0xi0-qjIMA":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.456,"text":"The final part of this series is network"},{"start":2.456,"end":4.618,"text":"meta analysis, which compares many"},{"start":4.618,"end":7.13,"text":"treatments at once, even pairs that were"},{"start":7.13,"end":8.649,"text":"never tested head to head."},{"start":10.46,"end":13.005,"text":"Our example has 24 trials of four ways to"},{"start":13.005,"end":16.034,"text":"help people quit smoking: no contact, self"},{"start":16.034,"end":18.64,"text":"help, individual counseling, and group"},{"start":18.64,"end":19.306,"text":"counseling."},{"start":20.148,"end":22.984,"text":"Each line is a direct comparison, thicker"},{"start":22.984,"end":24.659,"text":"when more studies made it."},{"start":25.046,"end":27.624,"text":"Individual counseling versus no contact"},{"start":27.624,"end":30.073,"text":"was tested fifteen times, but group"},{"start":30.073,"end":32.651,"text":"counseling versus no contact only twice."},{"start":33.515,"end":35.826,"text":"Results are odds ratios, where a value"},{"start":35.826,"end":37.687,"text":"above one means more people quit."},{"start":39.493,"end":41.585,"text":"The key idea is indirect evidence."},{"start":41.954,"end":44.476,"text":"If we know how group counseling compares"},{"start":44.476,"end":46.814,"text":"with individual counseling, and how"},{"start":46.814,"end":49.213,"text":"individual counseling compares with no"},{"start":49.213,"end":51.674,"text":"contact, we can chain them to compare"},{"start":51.674,"end":53.704,"text":"group counseling with no contact."},{"start":54.55,"end":56.852,"text":"This rests on two assumptions:"},{"start":56.852,"end":59.218,"text":"transitivity, that the studies are"},{"start":59.218,"end":62.096000000000004,"text":"comparable, and consistency, that direct"},{"start":62.096000000000004,"end":63.887,"text":"and indirect evidence agree."},{"start":65.717,"end":68.322,"text":"Combining direct and indirect evidence,"},{"start":68.322,"end":70.989,"text":"every active treatment beats no contact on"},{"start":70.989,"end":71.485,"text":"average."},{"start":71.857,"end":74.09,"text":"Group counseling roughly doubles to"},{"start":74.09,"end":76.324,"text":"triples the odds of quitting, and"},{"start":76.324,"end":78.494,"text":"individual counseling doubles them."},{"start":79.324,"end":81.701,"text":"For self help, though, the interval"},{"start":81.701,"end":84.257,"text":"crosses one, so its benefit is uncertain."},{"start":85.1,"end":87.481,"text":"Heterogeneity is large, with I squared"},{"start":87.481,"end":89.979,"text":"near 89 percent, which is one reason the"},{"start":89.979,"end":91.082,"text":"intervals are wide."},{"start":97.12700000000001,"end":99.307,"text":"Take group versus individual counseling."},{"start":99.63499999999999,"end":101.924,"text":"Studies that compared them directly found"},{"start":101.924,"end":104.16,"text":"almost no difference, but the indirect"},{"start":104.16,"end":106.45,"text":"route suggests group counseling is better."},{"start":107.214,"end":110.15,"text":"That gap is not statistically clear on its"},{"start":110.15,"end":112.745,"text":"own, with p of zero point two eight."},{"start":113.155,"end":115.818,"text":"But across the whole network, a test"},{"start":115.818,"end":118.071,"text":"between study designs flags some"},{"start":118.071,"end":121.008,"text":"inconsistency, with p of zero point zero"},{"start":121.008,"end":124.081,"text":"three three, a warning to read the results"},{"start":124.081,"end":124.764,"text":"with care."},{"start":126.637,"end":128.808,"text":"Network meta analyses often rank the"},{"start":128.808,"end":129.454,"text":"treatments."},{"start":129.806,"end":132.388,"text":"Here group counseling ranks first, with a"},{"start":132.388,"end":134.325,"text":"P score of zero point eight four."},{"start":135.115,"end":137.103,"text":"But rankings hide uncertainty."},{"start":137.5,"end":139.952,"text":"Group and individual counseling have"},{"start":139.952,"end":142.736,"text":"heavily overlapping intervals, so first"},{"start":142.736,"end":144.857,"text":"and second place are not really"},{"start":144.857,"end":145.917,"text":"distinguishable."},{"start":147.827,"end":150.628,"text":"Report the shape of the network, how you"},{"start":150.628,"end":152.712,"text":"judged transitivity and checked"},{"start":152.712,"end":155.188,"text":"consistency, and effects with their"},{"start":155.188,"end":157.207,"text":"uncertainty before any ranking."},{"start":157.598,"end":160.334,"text":"That completes our step by step series on"},{"start":160.334,"end":161.246,"text":"meta analysis."}]},"xrfvYZc6XIY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.241,"text":"Part four repeats the random effects"},{"start":2.241,"end":4.894,"text":"analysis the Bayesian way, which answers a"},{"start":4.894,"end":6.426,"text":"question a p value cannot."},{"start":8.303,"end":11.295,"text":"In part two, the average effect was zero"},{"start":11.295,"end":14.148,"text":"point zero eight, with p of zero point"},{"start":14.148,"end":14.427,"text":"one."},{"start":14.844,"end":17.767,"text":"That tells us the data are not unusual if"},{"start":17.767,"end":19.576,"text":"the true effect were zero."},{"start":20.55,"end":22.922,"text":"It does not tell us how likely it is that"},{"start":22.922,"end":24.22,"text":"the effect is positive."},{"start":24.559,"end":25.801,"text":"Bayesian analysis can."},{"start":27.65,"end":29.612,"text":"Bayes' rule says the posterior is"},{"start":29.612,"end":31.69,"text":"proportional to the prior times the"},{"start":31.69,"end":34.229,"text":"likelihood: what we believed before,"},{"start":34.229,"end":36.134,"text":"updated by what the studies show."},{"start":36.947,"end":39.681,"text":"A prior is belief before the data, and a"},{"start":39.681,"end":41.525,"text":"posterior is belief after it."},{"start":43.427,"end":45.397,"text":"We need priors for two things."},{"start":45.791,"end":48.681,"text":"For tau, the spread of true effects, we"},{"start":48.681,"end":51.505,"text":"use a gentle half normal prior that allows"},{"start":51.505,"end":53.673,"text":"values from zero up to about one."},{"start":54.555,"end":56.967,"text":"After seeing the nineteen studies, the"},{"start":56.967,"end":59.497,"text":"posterior for tau concentrates around zero"},{"start":59.497,"end":62.145,"text":"point one four, very close to the estimate"},{"start":62.145,"end":62.852,"text":"in part two."},{"start":64.68299999999999,"end":67.673,"text":"For mu, the average effect, we use a very"},{"start":67.673,"end":70.403,"text":"wide prior, so the studies speak almost"},{"start":70.403,"end":71.963,"text":"entirely for themselves."},{"start":76.97,"end":80.078,"text":"The shaded area is the answer: about 94"},{"start":80.078,"end":82.90899999999999,"text":"percent of the posterior lies above zero."},{"start":83.32300000000001,"end":86.01599999999999,"text":"The effect is probably positive, but"},{"start":86.01599999999999,"end":88.986,"text":"small, and the data cannot rule out zero."},{"start":89.877,"end":92.432,"text":"The ninety five percent credible interval,"},{"start":92.432,"end":94.759,"text":"from minus zero point zero three to zero"},{"start":94.759,"end":97.2,"text":"point two one, can be read directly as a"},{"start":97.2,"end":99.69800000000001,"text":"probability statement, which a confidence"},{"start":99.69800000000001,"end":100.606,"text":"interval cannot."},{"start":102.42699999999999,"end":105.237,"text":"For a new, similar study, the Bayesian"},{"start":105.237,"end":107.982,"text":"predictive interval runs from about minus"},{"start":107.982,"end":110.596,"text":"zero point two eight to zero point four"},{"start":110.596,"end":113.47200000000001,"text":"seven, a little wider than in part two,"},{"start":113.47200000000001,"end":116.152,"text":"because uncertainty about tau is carried"},{"start":116.152,"end":116.675,"text":"through."},{"start":117.564,"end":120.137,"text":"With only nineteen studies, the prior for"},{"start":120.137,"end":122.419,"text":"tau can shift the results, so a good"},{"start":122.419,"end":124.759,"text":"Bayesian meta analysis reruns the model"},{"start":124.759,"end":127.157,"text":"with other reasonable priors and reports"},{"start":127.157,"end":128.503,"text":"how much things change."},{"start":130.327,"end":132.996,"text":"Report your priors and why, the posterior"},{"start":132.996,"end":135.362,"text":"summaries and probabilities, and how"},{"start":135.362,"end":137.364,"text":"sensitive they are to the priors."},{"start":137.728,"end":139.912,"text":"In the last part, we compare many"},{"start":139.912,"end":142.157,"text":"treatments at once with network meta"},{"start":142.157,"end":142.703,"text":"analysis."}]},"r_tqNkORPeo":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.544,"text":"This is the final part of our series on"},{"start":2.544,"end":5.09,"text":"sequential analytics: hidden Markov"},{"start":5.09,"end":5.524,"text":"models."},{"start":5.897,"end":8.443,"text":"The idea is that the codes we see may be"},{"start":8.443,"end":10.367,"text":"driven by states we cannot see."},{"start":12.193,"end":15.106,"text":"In session P001, we observe one code per"},{"start":15.106,"end":15.445,"text":"turn."},{"start":15.851,"end":18.764,"text":"A hidden Markov model assumes that beneath"},{"start":18.764,"end":21.609,"text":"each code sits a hidden state, which we"},{"start":21.609,"end":23.167,"text":"never observe directly."},{"start":24.041,"end":26.667,"text":"For a beginner, think of a hidden state as"},{"start":26.667,"end":29.06,"text":"a mode the conversation is in, such as"},{"start":29.06,"end":31.394,"text":"questioning or explaining, that shows"},{"start":31.394,"end":33.844,"text":"itself only through the codes it tends to"},{"start":33.844,"end":34.311,"text":"produce."},{"start":36.093,"end":38.046,"text":"The model describes those unseen"},{"start":38.046,"end":39.82,"text":"influences with three sets of"},{"start":39.82,"end":40.648,"text":"probabilities."},{"start":41.461,"end":43.767,"text":"Initial probabilities say how sessions"},{"start":43.767,"end":44.122,"text":"start."},{"start":44.477,"end":46.664,"text":"Transition probabilities say how one"},{"start":46.664,"end":48.497,"text":"hidden state leads to the next."},{"start":48.852,"end":51.157,"text":"Emission probabilities say which codes"},{"start":51.157,"end":53.227,"text":"each hidden state tends to produce."},{"start":54.029,"end":56.366,"text":"The word emission simply means the code a"},{"start":56.366,"end":57.256,"text":"state gives off."},{"start":59.06,"end":61.391,"text":"The probabilities are estimated with the E"},{"start":61.391,"end":63.559,"text":"M algorithm, which alternates between"},{"start":63.559,"end":65.727,"text":"guessing the hidden states and updating"},{"start":65.727,"end":67.895,"text":"the probabilities until nothing changes."},{"start":68.67699999999999,"end":71.289,"text":"E M can stop at a local peak, so we start"},{"start":71.289,"end":73.01,"text":"it from twenty random places."},{"start":73.366,"end":76.037,"text":"For the 6 state model, every start reached"},{"start":76.037,"end":78.293,"text":"the same log likelihood, a sign the"},{"start":78.293,"end":79.42099999999999,"text":"solution is stable."},{"start":81.275,"end":83.754,"text":"How many hidden states should there be?"},{"start":84.135,"end":86.742,"text":"We fit models with two to ten states and"},{"start":86.742,"end":89.475,"text":"compare them with the Bayesian information"},{"start":89.475,"end":90.873,"text":"criterion, or B I C."},{"start":98.893,"end":100.614,"text":"B I C is lowest at 6 states."},{"start":100.983,"end":103.565,"text":"More states keep improving the raw fit,"},{"start":103.565,"end":106.148,"text":"but the penalty for extra parameters wins"},{"start":106.148,"end":106.824,"text":"after that."},{"start":108.693,"end":111.15100000000001,"text":"Here are the emissions of the 6 states."},{"start":111.529,"end":114.113,"text":"Each row is a state, and its strongest"},{"start":114.113,"end":116.445,"text":"cells tell us what that state mostly"},{"start":116.445,"end":119.09100000000001,"text":"produces: one state is almost always"},{"start":119.09100000000001,"end":121.675,"text":"explain, another almost always example."},{"start":122.55,"end":125.7,"text":"The transitions reveal something striking."},{"start":126.15,"end":129.075,"text":"The states fall into two closed groups"},{"start":129.075,"end":132.075,"text":"that never pass into each other: a"},{"start":132.075,"end":135.45,"text":"question and answer loop, and a chain from"},{"start":135.45,"end":137.85,"text":"explain to example to elaborate."},{"start":139.793,"end":142.836,"text":"For any session, the model can recover the"},{"start":142.836,"end":145.81,"text":"single most likely path of hidden states,"},{"start":145.81,"end":147.433,"text":"called the Viterbi path."},{"start":147.838,"end":150.678,"text":"Here it is for P001, one turn at a time."},{"start":156.06,"end":158.883,"text":"This session never leaves the chain group:"},{"start":158.883,"end":161.412,"text":"explain leads to example, and example to"},{"start":161.412,"end":163.117,"text":"elaborate, turn after turn."},{"start":164.927,"end":167.361,"text":"The model was never told which group each"},{"start":167.361,"end":168.404,"text":"session came from."},{"start":168.751,"end":171.011,"text":"Yet every control session stays in the"},{"start":171.011,"end":173.561,"text":"question and answer loop, while 38 of the"},{"start":173.561,"end":175.879,"text":"50 treatment sessions stay in the chain."},{"start":176.684,"end":179.034,"text":"So the hidden states sort the sessions in"},{"start":179.034,"end":181.385,"text":"a way that matches the real groups eighty"},{"start":181.385,"end":183.008,"text":"eight times out of a hundred."},{"start":184.81,"end":185.99,"text":"A word of caution."},{"start":186.383,"end":188.677,"text":"These data were simulated from two"},{"start":188.677,"end":191.233,"text":"ordinary Markov chains, one for each"},{"start":191.233,"end":193.658,"text":"group, with no hidden minds inside."},{"start":194.052,"end":196.214,"text":"The six states recover those two"},{"start":196.214,"end":199.29500000000002,"text":"processes, which is useful, but a state is"},{"start":199.29500000000002,"end":202.113,"text":"a modeling choice, not a discovery about"},{"start":202.113,"end":203.227,"text":"how people think."},{"start":205.127,"end":207.4,"text":"When you report a hidden Markov model,"},{"start":207.4,"end":209.895,"text":"state how the number of states was chosen,"},{"start":209.895,"end":212.28,"text":"whether the restarts agreed, and how the"},{"start":212.28,"end":214.054,"text":"states were labeled and checked."},{"start":215.827,"end":218.405,"text":"That completes the series: five lenses on"},{"start":218.405,"end":220.654,"text":"one stream of events, each answering a"},{"start":220.654,"end":222.79399999999998,"text":"different question about the same data."},{"start":223.123,"end":225.591,"text":"Pick the lens by your question, not by the"},{"start":225.591,"end":227.018,"text":"method that is in fashion."}]},"s0HYoN8dfIM":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.755,"text":"This series explains meta analysis step by"},{"start":2.755,"end":5.073,"text":"step, starting from the statistics."},{"start":5.449,"end":8.144,"text":"Part one covers effect sizes, the common"},{"start":8.144,"end":10.65,"text":"currency that lets different studies be"},{"start":10.65,"end":11.214,"text":"combined."},{"start":13.103,"end":15.928,"text":"Our running example is a classic: nineteen"},{"start":15.928,"end":18.399,"text":"studies of whether teachers' expectations"},{"start":18.399,"end":20.812,"text":"raise pupils' I Q scores, collected by"},{"start":20.812,"end":21.93,"text":"Stephen Raudenbush."},{"start":22.71,"end":24.99,"text":"A meta analysis is a study of studies."},{"start":25.35,"end":27.99,"text":"Before we can combine them, we need every"},{"start":27.99,"end":30.33,"text":"study to report its result on the same"},{"start":30.33,"end":30.69,"text":"scale."},{"start":32.527,"end":35.095,"text":"The studies used different tests, so raw"},{"start":35.095,"end":37.304,"text":"score differences cannot be compared"},{"start":37.304,"end":37.842,"text":"directly."},{"start":38.2,"end":40.888,"text":"Instead, we divide the difference in means"},{"start":40.888,"end":42.858,"text":"by the pooled standard deviation."},{"start":43.734,"end":46.993,"text":"The result, d, says how far apart the two"},{"start":46.993,"end":49.968,"text":"groups are, in standard deviation units."},{"start":50.86,"end":52.907,"text":"The standard deviation works here as a"},{"start":52.907,"end":54.796,"text":"common ruler that every test shares."},{"start":56.593,"end":58.972,"text":"Rosenthal and Jacobson's famous study"},{"start":58.972,"end":60.913,"text":"reported d of zero point three."},{"start":61.288,"end":63.166,"text":"Picture the two groups' score"},{"start":63.166,"end":65.42,"text":"distributions and slide one by that"},{"start":65.42,"end":65.858,"text":"amount."},{"start":73.38,"end":75.348,"text":"The curves still overlap heavily."},{"start":75.705,"end":78.03,"text":"Yet about 62 percent of the expectancy"},{"start":78.03,"end":80.355,"text":"group scores above the average control"},{"start":80.355,"end":82.383,"text":"pupil, instead of fifty percent."},{"start":83.237,"end":85.243,"text":"Cohen's rough labels would call this"},{"start":85.243,"end":85.568,"text":"small."},{"start":85.894,"end":88.44200000000001,"text":"In education, though, context matters more"},{"start":88.44200000000001,"end":90.882,"text":"than labels, because a cheap change with a"},{"start":90.882,"end":92.94200000000001,"text":"small effect can still be worth a lot."},{"start":94.737,"end":97.22,"text":"In small samples, d slightly overstates"},{"start":97.22,"end":98.402,"text":"the true difference."},{"start":98.757,"end":101.239,"text":"Hedges' correction shrinks it a little,"},{"start":101.239,"end":103.072,"text":"giving an effect size called g."},{"start":103.945,"end":107.44800000000001,"text":"The shrinkage is small: about two percent"},{"start":107.44800000000001,"end":110.35499999999999,"text":"for a study of 33 pupils, and almost"},{"start":110.35499999999999,"end":111.547,"text":"nothing for 457."},{"start":112.423,"end":114.80799999999999,"text":"This is a correction for bias, a tilt in"},{"start":114.80799999999999,"end":117.027,"text":"one direction, rather than for random"},{"start":117.027,"end":117.36,"text":"noise."},{"start":119.137,"end":121.17,"text":"Every effect size also comes with a"},{"start":121.17,"end":123.429,"text":"variance, which depends mostly on the"},{"start":123.429,"end":124.163,"text":"sample sizes."},{"start":124.502,"end":126.648,"text":"Bigger groups give a smaller variance."},{"start":127.454,"end":129.92,"text":"For Rosenthal and Jacobson, with sixty"},{"start":129.92,"end":132.446,"text":"five and two hundred fifty five pupils,"},{"start":132.446,"end":134.972,"text":"the variance is about zero point zero one"},{"start":134.972,"end":135.273,"text":"nine."},{"start":136.1,"end":138.906,"text":"Its square root is the standard error, and"},{"start":138.906,"end":141.088,"text":"the ninety five percent confidence"},{"start":141.088,"end":143.644,"text":"interval runs from about zero point zero"},{"start":143.644,"end":145.576,"text":"three to zero point five seven."},{"start":147.47,"end":149.958,"text":"Now every study becomes an estimate with"},{"start":149.958,"end":150.686,"text":"an interval."},{"start":151.05,"end":153.537,"text":"Big studies have short intervals and big"},{"start":153.537,"end":156.14600000000002,"text":"squares; small studies have long ones."},{"start":156.987,"end":159.992,"text":"Compare Fleming and Anttonen, with 457"},{"start":159.992,"end":163.436,"text":"pupils, to Pellegrini and Hicks, with only"},{"start":163.436,"end":166.80700000000002,"text":"33: the larger study is far more precise."},{"start":173.917,"end":176.551,"text":"So each study enters a meta analysis as"},{"start":176.551,"end":179.251,"text":"two numbers: an effect size and its"},{"start":179.251,"end":179.844,"text":"variance."},{"start":180.239,"end":182.807,"text":"In part two, we use the variances to"},{"start":182.807,"end":185.442,"text":"decide how much each study should count."}]},"spTunL0povM":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.653,"text":"In part one, each study became an effect"},{"start":2.653,"end":3.914,"text":"size with a variance."},{"start":4.275,"end":6.978,"text":"Part two asks how to combine them, and how"},{"start":6.978,"end":8.72,"text":"much each study should count."},{"start":10.583,"end":12.849,"text":"The standard answer is to weight each"},{"start":12.849,"end":15.412,"text":"study by the inverse of its variance, so"},{"start":15.412,"end":17.678,"text":"precise studies count more than noisy"},{"start":17.678,"end":17.976,"text":"ones."},{"start":19.77,"end":22.024,"text":"With these weights, the largest study"},{"start":22.024,"end":24.335,"text":"carries about 15 percent of the total,"},{"start":24.335,"end":26.701,"text":"while the smallest carries well under one"},{"start":26.701,"end":27.152,"text":"percent."},{"start":27.97,"end":30.674,"text":"If we assume every study estimates one and"},{"start":30.674,"end":33.504,"text":"the same true effect, the weighted average"},{"start":33.504,"end":36.208,"text":"is zero point zero six, with an interval"},{"start":36.208,"end":37.403,"text":"that includes zero."},{"start":42.407,"end":43.911,"text":"The Q test answers this."},{"start":44.287,"end":46.858,"text":"If only sampling noise were at work, Q"},{"start":46.858,"end":48.299,"text":"would be near eighteen."},{"start":48.676,"end":51.371,"text":"It is thirty five point eight, with p of"},{"start":51.371,"end":54.192,"text":"zero point zero zero seven: the studies"},{"start":54.192,"end":56.261,"text":"disagree more than chance allows."},{"start":59.07,"end":61.089,"text":"A random effects model drops that"},{"start":61.089,"end":61.742,"text":"assumption."},{"start":62.098,"end":64.354,"text":"Each study has its own true effect,"},{"start":64.354,"end":66.432,"text":"scattered around an average with a"},{"start":66.432,"end":68.985,"text":"standard deviation called tau, estimated"},{"start":68.985,"end":71.004,"text":"here at about zero point one four."},{"start":72.787,"end":75.488,"text":"Adding tau squared to every variance makes"},{"start":75.488,"end":78.439,"text":"the weights more equal: the largest study"},{"start":78.439,"end":80.952,"text":"now carries about 10 percent instead of"},{"start":80.952,"end":81.14,"text":"15."},{"start":83.017,"end":84.681,"text":"Here is the full forest plot."},{"start":85.025,"end":87.149,"text":"The blue diamond is the fixed effect"},{"start":87.149,"end":89.444,"text":"estimate, and the teal diamond is the"},{"start":89.444,"end":91.912,"text":"random effects estimate, zero point zero"},{"start":91.912,"end":94.265,"text":"eight four, with a wider interval that"},{"start":94.265,"end":95.412,"text":"still includes zero."},{"start":96.244,"end":98.11,"text":"The I squared statistic puts this"},{"start":98.11,"end":100.636,"text":"heterogeneity in proportion: about forty"},{"start":100.636,"end":102.997,"text":"two percent of the variation reflects real"},{"start":102.997,"end":104.53399999999999,"text":"differences between studies."},{"start":105.28,"end":107.646,"text":"The yellow line is the prediction"},{"start":107.646,"end":110.708,"text":"interval, from about minus zero point two"},{"start":110.708,"end":113.7,"text":"to plus zero point three seven: a new"},{"start":113.7,"end":116.761,"text":"study's true effect could be negative, or"},{"start":116.761,"end":118.15299999999999,"text":"moderately positive."},{"start":120.05,"end":122.077,"text":"Report the model and how tau was"},{"start":122.077,"end":124.658,"text":"estimated, the pooled estimate with its"},{"start":124.658,"end":127.545,"text":"interval, and the heterogeneity, including"},{"start":127.545,"end":129.02,"text":"the prediction interval."},{"start":129.388,"end":131.968,"text":"In part three, we ask why these studies"},{"start":131.968,"end":132.52100000000002,"text":"disagree."}]},"9gPGEZsnIPg":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.81,"text":"In part two, the studies disagreed more"},{"start":2.81,"end":4.05,"text":"than chance allows."},{"start":4.441,"end":7.116,"text":"Part three asks why they disagree, and"},{"start":7.116,"end":9.269,"text":"whether some results are missing."},{"start":11.16,"end":12.698,"text":"Raudenbush had a hypothesis."},{"start":13.028,"end":15.225,"text":"Telling teachers that some pupils would"},{"start":15.225,"end":17.587,"text":"bloom should matter most when the teachers"},{"start":17.587,"end":19.07,"text":"barely knew the pupils yet."},{"start":19.898,"end":22.521,"text":"Each bubble is a study, placed by how many"},{"start":22.521,"end":24.969,"text":"weeks the teachers had known the class,"},{"start":24.969,"end":26.368,"text":"and sized by its weight."},{"start":32.376,"end":34.545,"text":"The large positive effects all come from"},{"start":34.545,"end":36.503,"text":"studies where teachers had known the"},{"start":36.503,"end":37.878,"text":"pupils for a week or less."},{"start":38.633,"end":40.897,"text":"A study feature that changes the size of"},{"start":40.897,"end":43.217,"text":"an effect, like this one, is called a"},{"start":43.217,"end":45.591,"text":"moderator, and it can be tested formally."},{"start":47.383,"end":49.806,"text":"Splitting the studies tells a clear story."},{"start":50.152,"end":52.344,"text":"With a week or less of contact, the"},{"start":52.344,"end":54.709,"text":"average effect is about zero point three"},{"start":54.709,"end":55.055,"text":"seven."},{"start":55.401,"end":57.939,"text":"With two weeks or more, it is essentially"},{"start":57.939,"end":58.227,"text":"zero."},{"start":59.001,"end":61.176,"text":"A meta regression with this moderator"},{"start":61.176,"end":63.008,"text":"explains essentially all of the"},{"start":63.008,"end":65.583,"text":"heterogeneity: the leftover tau squared"},{"start":65.583,"end":66.728,"text":"drops to about zero."},{"start":67.489,"end":70.252,"text":"One caution: studies were not randomly"},{"start":70.252,"end":72.953,"text":"assigned to their moderator values, so a"},{"start":72.953,"end":75.653,"text":"moderator finding is an association across"},{"start":75.653,"end":77.662,"text":"studies, not proof of a cause."},{"start":79.56,"end":81.92699999999999,"text":"To check for missing results, we draw a"},{"start":81.92699999999999,"end":84.631,"text":"funnel plot: big, precise studies at the"},{"start":84.631,"end":86.773,"text":"top, small ones spreading out below."},{"start":87.111,"end":89.30799999999999,"text":"Without bias, the points should look"},{"start":89.30799999999999,"end":89.872,"text":"symmetric."},{"start":90.678,"end":93.493,"text":"Here the small studies lean to the right,"},{"start":93.493,"end":95.988,"text":"and Egger's regression test flags that"},{"start":95.988,"end":98.738,"text":"asymmetry, with p of zero point zero one"},{"start":98.738,"end":98.994,"text":"two."},{"start":99.805,"end":101.957,"text":"Trim and fill imagines the 3 missing"},{"start":101.957,"end":104.458,"text":"studies that would restore symmetry, and"},{"start":104.458,"end":106.726,"text":"the adjusted estimate shrinks to about"},{"start":106.726,"end":108.006,"text":"zero point zero three."},{"start":108.793,"end":110.45400000000001,"text":"Notice the colors, though."},{"start":110.81,"end":113.47999999999999,"text":"The small, positive studies are mostly the"},{"start":113.47999999999999,"end":116.031,"text":"early contact ones, so the asymmetry may"},{"start":116.031,"end":118.523,"text":"reflect the moderator rather than missing"},{"start":118.523,"end":118.99799999999999,"text":"studies."},{"start":119.354,"end":121.787,"text":"Funnel asymmetry has more than one cause."},{"start":123.66,"end":125.947,"text":"Report which moderators you planned to"},{"start":125.947,"end":128.704,"text":"test, how much heterogeneity they explain,"},{"start":128.704,"end":131.049,"text":"and how you checked for missing studies."},{"start":131.401,"end":133.806,"text":"In part four, we redo the analysis the"},{"start":133.806,"end":134.568,"text":"Bayesian way."}]},"k9izMqIyRXw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.315,"text":"Here is a question calculus was built to"},{"start":2.315,"end":2.7,"text":"answer."},{"start":3.158,"end":5.384,"text":"Take a pair of axes, and draw the curve x"},{"start":5.384,"end":6.244,"text":"squared over two."},{"start":6.665,"end":9.01,"text":"How much space lies under it, from zero to"},{"start":9.01,"end":9.322,"text":"three?"},{"start":9.753,"end":12.151,"text":"Curves are hard, but rectangles are easy."},{"start":12.486,"end":14.828,"text":"Fill the region with three of them, and"},{"start":14.828,"end":15.888,"text":"add up their areas."},{"start":16.37,"end":18.315,"text":"Make them thinner, and the gaps shrink."},{"start":19.043,"end":21.482,"text":"Thinner still, and the sum creeps closer."},{"start":21.901,"end":24.367,"text":"In the limit, the rectangles become the"},{"start":24.367,"end":26.658,"text":"curve itself, and the sum becomes an"},{"start":26.658,"end":28.948,"text":"integral: exactly four and a half."},{"start":29.398,"end":31.88,"text":"The area under a curve is just infinitely"},{"start":31.88,"end":33.593,"text":"many thin slices, added up."}]},"dqrWUnItTi4":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.411,"text":"This is part three of our series on"},{"start":2.411,"end":5.415,"text":"sequential analytics: transition network"},{"start":5.415,"end":8.354,"text":"analysis, or T N A, with a focus on what"},{"start":8.354,"end":10.966,"text":"each number means and how reliable each"},{"start":10.966,"end":11.488,"text":"edge is."},{"start":13.297,"end":15.58,"text":"Transition network analysis starts from"},{"start":15.58,"end":18.035,"text":"the same lag one transitions we counted in"},{"start":18.035,"end":20.319,"text":"part one, four thousand thirty six of"},{"start":20.319,"end":20.604,"text":"them."},{"start":21.404,"end":23.889,"text":"Instead of comparing counts with chance,"},{"start":23.889,"end":26.489,"text":"it divides each row by its total, so every"},{"start":26.489,"end":28.8,"text":"row becomes a set of probabilities that"},{"start":28.8,"end":29.667,"text":"adds up to one."},{"start":30.431,"end":32.919,"text":"So ask is followed by explain with a"},{"start":32.919,"end":35.879,"text":"probability of zero point five three, the"},{"start":35.879,"end":37.897,"text":"same value we saw in part one."},{"start":38.768,"end":41.407,"text":"This is a first order Markov model: the"},{"start":41.407,"end":43.928,"text":"next code is assumed to depend only on the"},{"start":43.928,"end":46.216,"text":"current one, not on anything earlier."},{"start":48.005,"end":50.614,"text":"Drawn as a network, each code is a node,"},{"start":50.614,"end":53.106,"text":"and each transition is an arrow, thicker"},{"start":53.106,"end":54.439,"text":"when it is more likely."},{"start":54.787,"end":57.048,"text":"The rings show a code following itself."},{"start":57.872,"end":60.783,"text":"The strongest path is ask to explain, at"},{"start":60.783,"end":63.829,"text":"zero point five three, followed by example"},{"start":63.829,"end":67.01,"text":"to elaborate, at zero point three six, and"},{"start":67.01,"end":69.92,"text":"explain back to ask, at zero point three"},{"start":69.92,"end":70.326,"text":"three."},{"start":71.229,"end":73.734,"text":"The model also records how sessions begin:"},{"start":73.734,"end":75.926,"text":"fifty four percent of them start with ask."},{"start":76.666,"end":79.072,"text":"Centrality measures summarize the role of"},{"start":79.072,"end":81.592,"text":"each node, and explain has the highest in"},{"start":81.592,"end":84.112,"text":"strength, one point two one, because it"},{"start":84.112,"end":86.345,"text":"receives the most probability from the"},{"start":86.345,"end":87.032,"text":"other codes."},{"start":88.804,"end":90.262,"text":"Is each edge reliable?"},{"start":90.66,"end":93.444,"text":"T N A resamples the sessions one thousand"},{"start":93.444,"end":96.295,"text":"times, refits the model each time, and"},{"start":96.295,"end":98.416,"text":"checks how much each edge moves."},{"start":99.301,"end":101.86099999999999,"text":"An edge is called stable when its weight"},{"start":101.86099999999999,"end":104.42099999999999,"text":"stays within seventy five to one hundred"},{"start":104.42099999999999,"end":106.669,"text":"twenty five percent of the original."},{"start":107.043,"end":109.479,"text":"Twenty three of twenty five edges pass."},{"start":109.85300000000001,"end":112.663,"text":"The two that do not are weak edges, ask to"},{"start":112.663,"end":114.536,"text":"example and example to itself."},{"start":115.378,"end":117.713,"text":"The bootstrap also gives intervals."},{"start":118.114,"end":120.65,"text":"For ask to explain, the ninety five"},{"start":120.65,"end":123.519,"text":"percent interval runs from zero point four"},{"start":123.519,"end":125.387,"text":"nine to zero point five six."},{"start":127.266,"end":130.359,"text":"To compare groups, T N A fits one network"},{"start":130.359,"end":133.24099999999999,"text":"per group, using the same nodes in the"},{"start":133.24099999999999,"end":134.084,"text":"same places."},{"start":134.953,"end":137.663,"text":"The largest difference is explain followed"},{"start":137.663,"end":140.69,"text":"by ask: zero point five zero in control,"},{"start":140.69,"end":143.274,"text":"but only zero point one one in treatment."},{"start":145.09,"end":147.672,"text":"A permutation test shuffles whole sessions"},{"start":147.672,"end":150.13400000000001,"text":"between the groups one thousand times,"},{"start":150.13400000000001,"end":152.837,"text":"refits both networks, and asks how often a"},{"start":152.837,"end":155.239,"text":"difference this large appears by chance."},{"start":156.036,"end":158.559,"text":"Seventeen of twenty five edges differ at p"},{"start":158.559,"end":160.788,"text":"below zero point zero five, and all"},{"start":160.788,"end":162.841,"text":"seventeen remain after a Benjamini"},{"start":162.841,"end":164.014,"text":"Hochberg correction."},{"start":164.863,"end":167.648,"text":"With one thousand shuffles, the smallest p"},{"start":167.648,"end":170.123,"text":"value the test can report is about zero"},{"start":170.123,"end":172.845,"text":"point zero zero one, so use more shuffles"},{"start":172.845,"end":174.392,"text":"if you need finer values."},{"start":176.261,"end":178.434,"text":"When you report a transition network"},{"start":178.434,"end":180.725,"text":"analysis, state how transitions were"},{"start":180.725,"end":183.309,"text":"counted, the probabilities and how stable"},{"start":183.309,"end":185.482,"text":"each edge was, and how groups were"},{"start":185.482,"end":187.773,"text":"compared, under a first order Markov"},{"start":187.773,"end":188.419,"text":"assumption."},{"start":189.238,"end":191.36599999999999,"text":"Next in the series is ordered network"},{"start":191.36599999999999,"end":193.718,"text":"analysis, which looks back over a wider"},{"start":193.718,"end":194.11,"text":"window."},{"start":194.446,"end":196.798,"text":"The companion guide has the code for this"},{"start":196.798,"end":197.582,"text":"analysis in R."}]},"0P0xOb9frbA":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.771,"text":"This is part one of a series on sequential"},{"start":2.771,"end":3.4,"text":"analytics."},{"start":3.777,"end":6.604,"text":"We begin with lag sequential analysis, the"},{"start":6.604,"end":9.242,"text":"approach popularized by Roger Bakeman and"},{"start":9.242,"end":12.006,"text":"his colleagues, with a focus on what each"},{"start":12.006,"end":12.823,"text":"number means."},{"start":14.667,"end":17.127,"text":"Lag sequential analysis asks a simple"},{"start":17.127,"end":20.365,"text":"question: given one code, how often does a"},{"start":20.365,"end":22.048,"text":"particular code come next?"},{"start":23.915,"end":25.818,"text":"The data points are transitions."},{"start":26.175,"end":28.673,"text":"Each pair of neighboring turns is one lag"},{"start":28.673,"end":31.052,"text":"one transition, counted only within a"},{"start":31.052,"end":31.528,"text":"session."},{"start":32.312,"end":34.925,"text":"So four thousand one hundred thirty six"},{"start":34.925,"end":37.538,"text":"turns in one hundred sessions give four"},{"start":37.538,"end":40.347,"text":"thousand thirty six transitions, because"},{"start":40.347,"end":42.895,"text":"no transition crosses from one session"},{"start":42.895,"end":43.81,"text":"into the next."},{"start":45.64,"end":48.124,"text":"Tallying them gives a five by five table:"},{"start":48.124,"end":50.186,"text":"the rows are the given code, and the"},{"start":50.186,"end":52.142,"text":"columns are the code that comes next."},{"start":52.938,"end":55.385,"text":"Ask was followed by explain four hundred"},{"start":55.385,"end":57.952,"text":"seventy eight times, out of nine hundred"},{"start":57.952,"end":60.22,"text":"six transitions that started with ask."},{"start":60.578,"end":63.145,"text":"That is a transitional probability of zero"},{"start":63.145,"end":64.159,"text":"point five three."},{"start":65.026,"end":67.205,"text":"But explain is common in general: it"},{"start":67.205,"end":69.281,"text":"follows about twenty six percent of all"},{"start":69.281,"end":69.592,"text":"turns."},{"start":69.904,"end":72.084,"text":"A high probability alone does not tell us"},{"start":72.084,"end":73.744,"text":"whether the sequence is special."},{"start":75.464,"end":78.021,"text":"So we ask what independence would predict."},{"start":78.386,"end":80.944,"text":"The expected count is the row total times"},{"start":80.944,"end":83.075,"text":"the column total, divided by all"},{"start":83.075,"end":85.693,"text":"transitions: about two hundred thirty"},{"start":85.693,"end":86.05799999999999,"text":"eight."},{"start":86.92,"end":89.592,"text":"Bakeman and Quera recommend the adjusted"},{"start":89.592,"end":92.26400000000001,"text":"residual, which scales the gap between"},{"start":92.26400000000001,"end":94.74000000000001,"text":"observed and expected by its standard"},{"start":94.74000000000001,"end":95.131,"text":"error."},{"start":95.52199999999999,"end":98.259,"text":"For ask then explain, z is twenty point"},{"start":98.259,"end":98.519,"text":"six."},{"start":99.337,"end":101.733,"text":"Doing this for every cell gives a map of"},{"start":101.733,"end":104.069,"text":"which transitions occur more often than"},{"start":104.069,"end":106.757,"text":"chance, in red, and less often, in blue."},{"start":108.58500000000001,"end":111.413,"text":"With twenty five cells, some will pass one"},{"start":111.413,"end":113.36099999999999,"text":"point nine six by chance alone."},{"start":113.738,"end":114.869,"text":"Eighteen cells do."},{"start":115.24600000000001,"end":117.949,"text":"With a Bonferroni criterion of three point"},{"start":117.949,"end":119.708,"text":"zero nine, sixteen remain."},{"start":121.582,"end":123.749,"text":"There is one important catch in this"},{"start":123.749,"end":124.1,"text":"table."},{"start":124.451,"end":126.793,"text":"It pools four thousand transitions from"},{"start":126.793,"end":128.901,"text":"one hundred sessions, as if every"},{"start":128.901,"end":131.536,"text":"transition were independent, and with that"},{"start":131.536,"end":133.468,"text":"many, almost any pattern looks"},{"start":133.468,"end":134.171,"text":"significant."},{"start":134.959,"end":137.531,"text":"Bakeman and colleagues therefore suggest"},{"start":137.531,"end":140.29,"text":"computing an index for each session, such"},{"start":140.29,"end":143.05,"text":"as Yule's Q, which runs from minus one to"},{"start":143.05,"end":145.12,"text":"plus one, with zero meaning no"},{"start":145.12,"end":145.873,"text":"association."},{"start":147.716,"end":150.034,"text":"Now each session contributes one number."},{"start":150.382,"end":152.75900000000001,"text":"Ask followed by explain is clearly above"},{"start":152.75900000000001,"end":153.918,"text":"zero in both groups."},{"start":154.774,"end":157.40699999999998,"text":"Comparing the groups tells a quieter"},{"start":157.40699999999998,"end":157.834,"text":"story."},{"start":158.261,"end":161.393,"text":"The control mean is zero point six three,"},{"start":161.393,"end":164.383,"text":"and the treatment mean is zero point five"},{"start":164.383,"end":167.514,"text":"three, a Welch t of one point nine two,"},{"start":167.514,"end":170.077,"text":"with p of zero point zero five nine."},{"start":170.942,"end":173.251,"text":"The pooled z scores, fifteen point nine"},{"start":173.251,"end":175.505,"text":"and eleven point four, would have made"},{"start":175.505,"end":177.869,"text":"this difference look far more certain than"},{"start":177.869,"end":178.199,"text":"it is."},{"start":178.528,"end":180.947,"text":"The session, not the transition, is the"},{"start":180.947,"end":181.992,"text":"unit for inference."},{"start":183.78,"end":186.431,"text":"When you report a lag sequential analysis,"},{"start":186.431,"end":188.72899999999998,"text":"state the lag and how transitions were"},{"start":188.72899999999998,"end":191.381,"text":"counted, the residuals and how you handled"},{"start":191.381,"end":193.855,"text":"many cells, and the session level index"},{"start":193.855,"end":195.446,"text":"you used to compare groups."},{"start":196.267,"end":198.721,"text":"Next in the series is sequential pattern"},{"start":198.721,"end":201.236,"text":"mining, which looks beyond a single lag."},{"start":201.595,"end":204.109,"text":"The companion guide has the code for this"},{"start":204.109,"end":204.947,"text":"analysis in R."}]},"V5HiWnlkp5E":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.182,"text":"This video explains ordered network"},{"start":2.182,"end":4.822,"text":"analysis, or O N A, with a focus on what"},{"start":4.822,"end":7.169,"text":"each number means and which data points"},{"start":7.169,"end":8.108,"text":"stand behind it."},{"start":9.957,"end":12.674,"text":"O N A starts from an event log, with one"},{"start":12.674,"end":15.517,"text":"coded turn per row, ordered in time within"},{"start":15.517,"end":16.338,"text":"each session."},{"start":17.154,"end":19.607,"text":"Here we have four thousand one hundred"},{"start":19.607,"end":21.871,"text":"thirty six turns, but one hundred"},{"start":21.871,"end":22.437,"text":"sessions."},{"start":22.814,"end":25.582,"text":"Each session is one unit of analysis, and"},{"start":25.582,"end":27.972,"text":"it will become one point in the final"},{"start":27.972,"end":28.286,"text":"plot."},{"start":30.161,"end":33.054,"text":"The most important setting is the window:"},{"start":33.054,"end":35.639,"text":"each turn is treated as a response, and"},{"start":35.639,"end":38.101,"text":"the four turns before it are its ground."},{"start":38.889,"end":41.34,"text":"For every ground code, the model adds one"},{"start":41.34,"end":43.736,"text":"count to a directed connection, from the"},{"start":43.736,"end":45.574,"text":"ground code to the response code."},{"start":47.325,"end":49.394,"text":"Sliding the window across the whole"},{"start":49.394,"end":52.151,"text":"session fills a five by five table: twenty"},{"start":52.151,"end":54.507,"text":"five directed connections, including a"},{"start":54.507,"end":55.771,"text":"code following itself."},{"start":56.622,"end":59.099,"text":"Order is what makes the network ordered."},{"start":59.471,"end":62.071,"text":"Agree followed by elaborate and elaborate"},{"start":62.071,"end":64.858,"text":"followed by agree are separate cells, with"},{"start":64.858,"end":66.901,"text":"12 and 18 counts in this session."},{"start":68.75,"end":70.945,"text":"Longer sessions produce larger counts."},{"start":71.292,"end":73.66,"text":"So each session's twenty five counts are"},{"start":73.66,"end":75.855,"text":"divided by the length of that list of"},{"start":75.855,"end":78.282,"text":"counts, the square root of their summed"},{"start":78.282,"end":78.744,"text":"squares."},{"start":79.56700000000001,"end":81.828,"text":"The counts become weights, and every"},{"start":81.828,"end":84.379,"text":"session now has the same total length, so"},{"start":84.379,"end":86.582,"text":"sessions are compared by the shape of"},{"start":86.582,"end":89.017,"text":"their connections, not by how long they"},{"start":89.017,"end":89.249,"text":"ran."},{"start":91.044,"end":93.189,"text":"A singular value decomposition then"},{"start":93.189,"end":95.691,"text":"reduces the twenty five dimensions to two"},{"start":95.691,"end":95.989,"text":"axes."},{"start":96.34700000000001,"end":97.777,"text":"Each dot is one session."},{"start":98.582,"end":101.194,"text":"The first axis captures 52 percent of the"},{"start":101.194,"end":103.557,"text":"variance, and the second 11 percent."},{"start":103.93,"end":106.729,"text":"The codes are placed in the same space, so"},{"start":106.729,"end":109.27799999999999,"text":"a session's dot sits toward the codes it"},{"start":109.27799999999999,"end":110.149,"text":"connects most."},{"start":110.989,"end":113.239,"text":"The squares are the treatment mean and the"},{"start":113.239,"end":115.384,"text":"control mean, with ninety five percent"},{"start":115.384,"end":116.483,"text":"confidence intervals."},{"start":116.797,"end":118.89,"text":"The two groups sit on opposite sides of"},{"start":118.89,"end":119.675,"text":"the first axis."},{"start":120.437,"end":122.891,"text":"Averaging the weights within each group"},{"start":122.891,"end":124.18,"text":"gives a mean network."},{"start":124.548,"end":126.695,"text":"The subtracted network shows their"},{"start":126.695,"end":129.457,"text":"difference: teal arrows are stronger in"},{"start":129.457,"end":132.218,"text":"treatment, and gold arrows are stronger in"},{"start":132.218,"end":132.709,"text":"control."},{"start":133.554,"end":136.386,"text":"In treatment, example leads to elaborate"},{"start":136.386,"end":137.439,"text":"much more often."},{"start":137.834,"end":140.14,"text":"In control, explain leads to ask."},{"start":140.535,"end":143.301,"text":"These are differences in structure, not"},{"start":143.301,"end":144.289,"text":"just in volume."},{"start":146.162,"end":148.238,"text":"To test the separation, take each"},{"start":148.238,"end":150.372,"text":"session's position on the first axis."},{"start":150.718,"end":152.96699999999998,"text":"The treatment mean is minus zero point"},{"start":152.96699999999998,"end":155.447,"text":"three five, and the control mean is plus"},{"start":155.447,"end":156.716,"text":"zero point three five."},{"start":157.54,"end":160.347,"text":"A Welch t test on that axis gives t of"},{"start":160.347,"end":163.515,"text":"twenty point one, p well below zero point"},{"start":163.515,"end":166.46699999999998,"text":"zero zero one, and a Cohen's d of four"},{"start":166.46699999999998,"end":168.914,"text":"point zero, a very large effect."},{"start":169.346,"end":172.442,"text":"On the second axis, d is only zero point"},{"start":172.442,"end":175.538,"text":"two seven, with p of zero point one nine."},{"start":176.426,"end":178.139,"text":"A permutation test makes fewer"},{"start":178.139,"end":178.802,"text":"assumptions."},{"start":179.133,"end":181.509,"text":"Shuffle the condition labels five thousand"},{"start":181.509,"end":183.94,"text":"times, recompute the distance between the"},{"start":183.94,"end":186.094,"text":"two means each time, and compare the"},{"start":186.094,"end":187.807,"text":"observed distance to that null"},{"start":187.807,"end":188.525,"text":"distribution."},{"start":189.303,"end":191.855,"text":"The observed distance of zero point seven"},{"start":191.855,"end":194.224,"text":"is far beyond anything chance produced."},{"start":194.589,"end":197.07999999999998,"text":"Keep in mind that these synthetic groups"},{"start":197.07999999999998,"end":199.632,"text":"were built to differ, so real data will"},{"start":199.632,"end":201.029,"text":"rarely look this clean."},{"start":202.881,"end":205.242,"text":"When you report ordered network analysis,"},{"start":205.242,"end":207.442,"text":"state the unit and the window, how the"},{"start":207.442,"end":209.803,"text":"counts were normalized and projected, and"},{"start":209.803,"end":212.164,"text":"how the group difference was tested, with"},{"start":212.164,"end":212.969,"text":"an effect size."},{"start":213.75900000000001,"end":216.167,"text":"The companion guide runs the same model in"},{"start":216.167,"end":216.279,"text":"R."},{"start":216.614,"end":218.85399999999998,"text":"Try a smaller or a larger window, and"},{"start":218.85399999999998,"end":220.53300000000002,"text":"watch how the network changes."}]},"KHzwP0eMwTk":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.285,"text":"This video explains sequential pattern"},{"start":2.285,"end":4.738,"text":"mining, with a focus on what each number"},{"start":4.738,"end":7.077,"text":"means and which data points stand behind"},{"start":7.077,"end":7.248,"text":"it."},{"start":9.068,"end":11.295,"text":"Everything starts from an event log."},{"start":11.666,"end":14.635,"text":"Each row is one coded turn: a session, a"},{"start":14.635,"end":17.047,"text":"turn number, a speaker, and a code."},{"start":17.885,"end":19.93,"text":"Sorting the rows by turn turns each"},{"start":19.93,"end":22.033,"text":"session into one ordered sequence of"},{"start":22.033,"end":22.374,"text":"codes."},{"start":23.172,"end":25.531,"text":"In our synthetic example there are four"},{"start":25.531,"end":27.772,"text":"thousand one hundred thirty six coded"},{"start":27.772,"end":30.425,"text":"turns, but only one hundred sessions:"},{"start":30.425,"end":32.902,"text":"fifty in a treatment group and fifty in a"},{"start":32.902,"end":33.728,"text":"control group."},{"start":34.53,"end":36.053,"text":"That difference matters."},{"start":36.434,"end":39.227,"text":"In pattern mining, the session, not the"},{"start":39.227,"end":41.639,"text":"turn, is the unit that gets counted."},{"start":43.457,"end":46.692,"text":"To see how counting works, take five short"},{"start":46.692,"end":50.36,"text":"sessions, and one candidate pattern: ask,"},{"start":50.36,"end":52.445,"text":"then explain, then example."},{"start":53.394,"end":55.556,"text":"A session contains the pattern if the"},{"start":55.556,"end":57.889,"text":"three codes appear in that order, even"},{"start":57.889,"end":59.481,"text":"with other turns in between."},{"start":59.823,"end":62.098,"text":"Sessions one, two, and five qualify."},{"start":62.44,"end":64.203,"text":"Sessions three and four do not."},{"start":64.982,"end":67.492,"text":"Session two contains the pattern twice,"},{"start":67.492,"end":69.284,"text":"but it still counts only once."},{"start":70.11,"end":72.478,"text":"So the support of the pattern is three out"},{"start":72.478,"end":74.57,"text":"of five sessions, or zero point six."},{"start":76.31700000000001,"end":78.902,"text":"Support describes how common a pattern is."},{"start":79.271,"end":82.226,"text":"Confidence asks a conditional question: of"},{"start":82.226,"end":84.872,"text":"the sessions with ask then explain, what"},{"start":84.872,"end":86.47200000000001,"text":"share go on to an example?"},{"start":86.842,"end":88.688,"text":"Here, zero point seven five."},{"start":89.544,"end":91.73400000000001,"text":"But a high confidence can mislead."},{"start":92.12100000000001,"end":94.697,"text":"An example appears in eighty percent of"},{"start":94.697,"end":97.14500000000001,"text":"all sessions anyway, so the lift,"},{"start":97.14500000000001,"end":99.91499999999999,"text":"confidence divided by that base rate, is"},{"start":99.91499999999999,"end":101.654,"text":"about zero point nine four."},{"start":102.041,"end":104.811,"text":"Ask and explain do not make an example any"},{"start":104.811,"end":106.80799999999999,"text":"more likely than it already is."},{"start":108.632,"end":109.944,"text":"Back to the real data."},{"start":110.30199999999999,"end":112.806,"text":"When any number of turns may separate the"},{"start":112.806,"end":115.43,"text":"codes, almost every short pattern appears"},{"start":115.43,"end":116.86099999999999,"text":"in nearly every session."},{"start":117.219,"end":119.902,"text":"Support hits the ceiling, and it no longer"},{"start":119.902,"end":121.154,"text":"tells patterns apart."},{"start":121.989,"end":123.913,"text":"Requiring the codes to occur in"},{"start":123.913,"end":126.19800000000001,"text":"consecutive turns restores the spread."},{"start":126.559,"end":129.265,"text":"That gap rule is a modeling choice, and it"},{"start":129.265,"end":130.828,"text":"should always be reported."},{"start":132.677,"end":135.551,"text":"The minimum support threshold is a second"},{"start":135.551,"end":136.03,"text":"choice."},{"start":136.44,"end":139.383,"text":"At zero point one, one hundred forty two"},{"start":139.383,"end":140.34,"text":"patterns pass."},{"start":140.751,"end":143.556,"text":"At zero point five, only thirty two do."},{"start":145.444,"end":146.865,"text":"Now a group question."},{"start":147.27100000000002,"end":150.114,"text":"The pattern example, explain, example"},{"start":150.114,"end":152.753,"text":"appears in thirty percent of treatment"},{"start":152.753,"end":155.799,"text":"sessions, and in twelve percent of control"},{"start":155.799,"end":156.40800000000002,"text":"sessions."},{"start":157.302,"end":159.93099999999998,"text":"Is a gap of eighteen points larger than"},{"start":159.93099999999998,"end":160.392,"text":"chance?"},{"start":160.786,"end":162.824,"text":"Turns within a session are not"},{"start":162.824,"end":165.585,"text":"independent, so a standard test on turn"},{"start":165.585,"end":168.017,"text":"counts would overstate the certainty."},{"start":168.9,"end":171.339,"text":"A permutation test keeps every session"},{"start":171.339,"end":173.715,"text":"intact, and shuffles only the group"},{"start":173.715,"end":176.529,"text":"labels, five thousand times, recomputing"},{"start":176.529,"end":177.655,"text":"the gap each time."},{"start":178.507,"end":181.058,"text":"This is the resulting null distribution."},{"start":181.44,"end":184.183,"text":"Our observed gap sits in its tail, for a"},{"start":184.183,"end":186.861,"text":"two sided p value of zero point zero four"},{"start":186.861,"end":187.244,"text":"seven."},{"start":188.114,"end":190.75900000000001,"text":"But we tested ninety two patterns, not"},{"start":190.75900000000001,"end":191.017,"text":"one."},{"start":191.404,"end":194.308,"text":"After a Benjamini Hochberg correction, the"},{"start":194.308,"end":196.889,"text":"adjusted value is zero point zero seven"},{"start":196.889,"end":199.405,"text":"eight, so this pattern should not be"},{"start":199.405,"end":201.276,"text":"called a reliable difference."},{"start":203.121,"end":205.528,"text":"When you report sequential pattern mining,"},{"start":205.528,"end":207.828,"text":"state the unit of analysis, the gap rule"},{"start":207.828,"end":210.128,"text":"and the support threshold, and how group"},{"start":210.128,"end":212.161,"text":"differences were tested and corrected."},{"start":212.978,"end":214.913,"text":"And remember that frequent patterns"},{"start":214.913,"end":216.148,"text":"describe what happened."},{"start":216.471,"end":218.942,"text":"They do not, on their own, explain why it"},{"start":218.942,"end":219.426,"text":"happened."},{"start":220.175,"end":222.452,"text":"The companion guide walks through the same"},{"start":222.452,"end":222.981,"text":"data in R."},{"start":223.299,"end":225.099,"text":"Try changing the gap rule and the"},{"start":225.099,"end":227.21699999999998,"text":"threshold, and watch how the patterns"},{"start":227.21699999999998,"end":227.588,"text":"change."}]},"Poo-UGoTyhw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.354,"text":"In this short video, we look at how people"},{"start":2.354,"end":4.597,"text":"learn from words and pictures, and at the"},{"start":4.597,"end":6.534,"text":"design principles that follow from it."},{"start":8.277,"end":10.263,"text":"Richard Mayer's cognitive theory of"},{"start":10.263,"end":12.194,"text":"multimedia learning rests on three"},{"start":12.194,"end":12.856,"text":"assumptions."},{"start":13.625,"end":15.448,"text":"First, we take in spoken words and"},{"start":15.448,"end":17.369,"text":"pictures through two separate channels."},{"start":18.112,"end":20.54,"text":"Second, each channel can hold only a"},{"start":20.54,"end":23.28,"text":"little at a time, so working memory fills"},{"start":23.28,"end":23.778,"text":"quickly."},{"start":24.609,"end":26.059,"text":"Third, learning is active."},{"start":26.37,"end":28.701,"text":"We connect the words and the pictures, and"},{"start":28.701,"end":30.618,"text":"we link them to what we already know."},{"start":32.417,"end":34.569,"text":"Because that capacity is limited, Mayer"},{"start":34.569,"end":36.67,"text":"describes three kinds of processing that"},{"start":36.67,"end":37.439,"text":"compete for it."},{"start":38.193,"end":40.704,"text":"Extraneous processing is effort wasted on"},{"start":40.704,"end":41.422,"text":"poor design."},{"start":41.781,"end":44.232,"text":"Essential processing represents the core"},{"start":44.232,"end":44.71,"text":"content."},{"start":45.069,"end":47.46,"text":"And generative processing is the deeper"},{"start":47.46,"end":49.075,"text":"work of making sense of it."},{"start":49.88,"end":51.791,"text":"In a cluttered lesson, extraneous"},{"start":51.791,"end":54.021,"text":"processing crowds out the generative work"},{"start":54.021,"end":55.242,"text":"that leads to learning."},{"start":56.047,"end":58.638,"text":"Good design reduces the extraneous load,"},{"start":58.638,"end":61.108,"text":"manages the essential load, and leaves"},{"start":61.108,"end":62.976,"text":"room for generative processing."},{"start":64.805,"end":66.805,"text":"Mayer's design principles can be grouped"},{"start":66.805,"end":68.122,"text":"by the demand they address."},{"start":68.892,"end":71.504,"text":"To reduce extraneous processing, cut what"},{"start":71.504,"end":74.116,"text":"is not needed, highlight what is, avoid"},{"start":74.116,"end":76.787,"text":"repeating the narration as on-screen text,"},{"start":76.787,"end":79.102,"text":"and place words near the pictures they"},{"start":79.102,"end":79.636,"text":"describe."},{"start":80.49,"end":83.106,"text":"To manage essential processing, break the"},{"start":83.106,"end":85.723,"text":"lesson into learner-paced segments, teach"},{"start":85.723,"end":88.339,"text":"the key terms first, and present words as"},{"start":88.339,"end":90.123,"text":"narration rather than as text."},{"start":90.908,"end":93.413,"text":"To foster generative processing, use a"},{"start":93.413,"end":96.28399999999999,"text":"conversational style, a natural voice, and"},{"start":96.28399999999999,"end":98.667,"text":"an on-screen guide who gestures toward"},{"start":98.667,"end":99.461,"text":"what matters."},{"start":101.285,"end":103.688,"text":"This video tries to follow its own advice."},{"start":104.031,"end":106.319,"text":"Most words are spoken, not printed,"},{"start":106.319,"end":108.72200000000001,"text":"highlights point to what matters, and a"},{"start":108.72200000000001,"end":110.782,"text":"guide gestures toward the key ideas."},{"start":111.602,"end":113.857,"text":"One principle deserves a closer look."},{"start":114.22200000000001,"end":116.904,"text":"The voice principle favors a human voice,"},{"start":116.904,"end":118.854,"text":"yet this narration is synthetic."},{"start":119.219,"end":121.84,"text":"Some studies suggest that modern synthetic"},{"start":121.84,"end":124.582,"text":"voices can work nearly as well, which is a"},{"start":124.582,"end":126.106,"text":"question worth examining."},{"start":127.899,"end":130.304,"text":"To put this into practice, pick a short"},{"start":130.304,"end":132.824,"text":"instructional video you have used, decide"},{"start":132.824,"end":135.114,"text":"which principle it follows and which it"},{"start":135.114,"end":137.405,"text":"breaks, and redesign one minute of it."},{"start":138.215,"end":140.192,"text":"Bring your example and your redesign to"},{"start":140.192,"end":142.36599999999999,"text":"the discussion board, and we will compare"},{"start":142.36599999999999,"end":142.959,"text":"notes there."}]}};
